  // ==========================================
  // 3. STATE MANAGEMENT METHODS
  // ==========================================
    let splashProgressInterval = null;
  let splashRafId = null;

  function initSplashSequence() {
    if (splashProgressInterval) {
      clearInterval(splashProgressInterval);
      splashProgressInterval = null;
    }
    if (splashRafId) {
      cancelAnimationFrame(splashRafId);
      splashRafId = null;
    }

    const duration = 2800; // 2.8s animasi terisi penuh dari kiri (0%) ke kanan (100%)
    const startTime = performance.now();

    const bar = document.getElementById('splash-telemetry-progress-bar');
    const text = document.getElementById('splash-telemetry-pct');
    if (bar) bar.style.width = '0%';
    if (text) text.textContent = '0%';

    function update(now) {
      if (AppState.currentScreen !== 'splash') {
        if (splashProgressInterval) clearInterval(splashProgressInterval);
        splashProgressInterval = null;
        if (splashRafId) cancelAnimationFrame(splashRafId);
        splashRafId = null;
        return;
      }

      const elapsed = (now || performance.now()) - startTime;
      const progressRatio = Math.min(1, Math.max(0, elapsed / duration));
      const pct = Math.min(100, Math.round(progressRatio * 100));

      const curBar = document.getElementById('splash-telemetry-progress-bar');
      const curText = document.getElementById('splash-telemetry-pct');
      if (curBar) {
        curBar.style.width = `${progressRatio * 100}%`;
      }
      if (curText) {
        curText.textContent = `${pct}%`;
      }

      if (progressRatio < 1) {
        splashRafId = requestAnimationFrame(update);
      } else {
        if (splashProgressInterval) clearInterval(splashProgressInterval);
        splashProgressInterval = null;
        if (splashRafId) cancelAnimationFrame(splashRafId);
        splashRafId = null;

        setTimeout(() => {
          if (AppState.currentScreen === 'splash') {
            navigateTo('login');
          }
        }, 350);
      }
    }

    splashRafId = requestAnimationFrame(update);

    // Interval sinkron cadangan agar animasi tetap berjalan stabil
    splashProgressInterval = setInterval(() => {
      if (AppState.currentScreen !== 'splash') {
        clearInterval(splashProgressInterval);
        splashProgressInterval = null;
        return;
      }
      const elapsed = performance.now() - startTime;
      const progressRatio = Math.min(1, Math.max(0, elapsed / duration));
      const pct = Math.min(100, Math.round(progressRatio * 100));

      const curBar = document.getElementById('splash-telemetry-progress-bar');
      const curText = document.getElementById('splash-telemetry-pct');
      if (curBar) {
        curBar.style.width = `${progressRatio * 100}%`;
      }
      if (curText) {
        curText.textContent = `${pct}%`;
      }

      if (progressRatio >= 1) {
        clearInterval(splashProgressInterval);
        splashProgressInterval = null;
      }
    }, 30);
  }

  function setState(partialState) {
    Object.assign(AppState, partialState);
    renderDOM();
    window.dispatchEvent(new CustomEvent('cosmos:statechange', { detail: AppState }));
  }

  // Pengarah & Status Transisi Motion Framer
  let currentNavDirection = 'forward'; // 'forward' | 'backward'
  let isNavigating = false;

  function navigateTo(screenName, extraProps = {}) {
    if (splashProgressInterval && screenName !== 'splash') {
      clearInterval(splashProgressInterval);
      splashProgressInterval = null;
    }
    if (AppState.currentScreen === screenName && Object.keys(extraProps).length === 0) {
      return;
    }
    if (isNavigating) return;

    currentNavDirection = 'forward';

    const container = document.getElementById('cosmos-screen-container');
    const safetyTimeout = setTimeout(() => { isNavigating = false; }, 260);

    const executeNav = () => {
      clearTimeout(safetyTimeout);
      isNavigating = false;
      AppState.previousScreens.push(AppState.currentScreen);
      Object.assign(AppState, {
        currentScreen: screenName,
        ...extraProps,
      });
      renderDOM();
      window.scrollTo({ top: 0, behavior: 'instant' });
    };

    // Jika di splash atau tanpa Motion Framer, jalankan langsung
    if (AppState.currentScreen === 'splash' || !container || !window.Motion || typeof window.Motion.animate !== 'function') {
      executeNav();
      return;
    }

    isNavigating = true;
    try {
      const anim = window.Motion.animate(
        container,
        {
          opacity: [1, 0],
          transform: ['translateY(0px) scale(1)', 'translateY(-12px) scale(0.992)'],
        },
        {
          duration: 0.13,
          easing: [0.32, 0, 0.67, 0],
        }
      );
      if (anim && anim.finished && typeof anim.finished.then === 'function') {
        anim.finished.then(executeNav).catch(executeNav);
      } else {
        setTimeout(executeNav, 130);
      }
    } catch (_) {
      executeNav();
    }
  }

  function goBack() {
    if (isNavigating) return;
    currentNavDirection = 'backward';

    const container = document.getElementById('cosmos-screen-container');
    const safetyTimeout = setTimeout(() => { isNavigating = false; }, 260);

    const executeBack = () => {
      clearTimeout(safetyTimeout);
      isNavigating = false;
      if (AppState.previousScreens.length > 0) {
        const prev = AppState.previousScreens.pop();
        AppState.currentScreen = prev;
      } else {
        AppState.currentScreen = 'beranda';
      }
      renderDOM();
      window.scrollTo({ top: 0, behavior: 'instant' });
    };

    if (AppState.currentScreen === 'splash' || !container || !window.Motion || typeof window.Motion.animate !== 'function') {
      executeBack();
      return;
    }

    isNavigating = true;
    try {
      const anim = window.Motion.animate(
        container,
        {
          opacity: [1, 0],
          transform: ['translateY(0px) scale(1)', 'translateY(12px) scale(0.992)'],
        },
        {
          duration: 0.13,
          easing: [0.32, 0, 0.67, 0],
        }
      );
      if (anim && anim.finished && typeof anim.finished.then === 'function') {
        anim.finished.then(executeBack).catch(executeBack);
      } else {
        setTimeout(executeBack, 130);
      }
    } catch (_) {
      executeBack();
    }
  }

  function toggleFavorite(planetId) {
    const idx = AppState.favorites.indexOf(planetId);
    if (idx > -1) {
      AppState.favorites.splice(idx, 1);
    } else {
      AppState.favorites.push(planetId);
    }
    renderDOM();
  }

