  // --- LAYAR 5: BERANDA (HOME DASHBOARD) ---
  // --- LAYAR 5: BERANDA (HOME OBSERVATORY & CELESTIAL DASHBOARD) ---
  function renderBerandaScreen() {
    const planet = PLANETS.find(p => p.id === (AppState.featuredPlanetId || 'jupiter')) || PLANETS[4];
    const accent = getAccentClass();

    return `
      <div class="flex flex-col w-full relative overflow-hidden select-none pb-28 md:pb-32 pt-2 md:pt-4">
        <!-- Celestial Observatory Backdrop & Dynamic Atmosphere Aura -->
        <div aria-hidden="true" class="absolute inset-0 pointer-events-none overflow-hidden z-0">
          <!-- Radiant Planetary Atmospheric Corona Bloom -->
          <div class="absolute top-1/2 left-1/2 lg:left-1/4 -translate-x-1/2 -translate-y-1/2 w-[340px] sm:w-[480px] lg:w-[620px] h-[340px] sm:h-[480px] lg:h-[620px] rounded-full blur-[110px] opacity-40 transition-all duration-700 pointer-events-none"
               style="background: radial-gradient(circle, ${planet.colorAccent} 0%, rgba(56,189,248,0.15) 50%, transparent 75%);"></div>

          <!-- Concentric Kepler Orbit Reticle & Celestial Coordinate Ticks -->
          <svg class="absolute top-1/2 left-1/2 lg:left-1/4 -translate-x-1/2 -translate-y-1/2 w-[600px] sm:w-[800px] lg:w-[960px] h-[600px] sm:h-[800px] lg:h-[960px] opacity-25 stroke-[#38bdf8] pointer-events-none" xmlns="http://www.w3.org/2000/svg" fill="none">
            <!-- Inner Orbit Guide -->
            <circle cx="50%" cy="50%" r="160" stroke-dasharray="3 8" stroke-width="0.8" />
            <!-- Mid Telemetry Ring -->
            <circle cx="50%" cy="50%" r="240" stroke-dasharray="6 14" stroke-width="0.6" />
            <!-- Outer Trajectory Ring -->
            <circle cx="50%" cy="50%" r="340" stroke-dasharray="2 10" stroke-width="0.5" />
            <circle cx="50%" cy="50%" r="440" stroke-dasharray="8 20" stroke-width="0.4" opacity="0.6" />
            <!-- Coordinate Crosshairs -->
            <line x1="50%" y1="0%" x2="50%" y2="100%" stroke-dasharray="4 8" stroke-width="0.5" opacity="0.3" />
            <line x1="0%" y1="50%" x2="100%" y2="50%" stroke-dasharray="4 8" stroke-width="0.5" opacity="0.3" />
            <!-- Degree Ticks -->
            <text x="51%" y="7%" fill="#38bdf8" font-size="10" font-family="'Space Grotesk', monospace" opacity="0.7">000° ECLIPTIC</text>
            <text x="93%" y="51%" fill="#38bdf8" font-size="10" font-family="'Space Grotesk', monospace" opacity="0.7">090°</text>
            <text x="51%" y="95%" fill="#38bdf8" font-size="10" font-family="'Space Grotesk', monospace" opacity="0.7">180° PERIHELION</text>
            <text x="2%" y="51%" fill="#38bdf8" font-size="10" font-family="'Space Grotesk', monospace" opacity="0.7">270°</text>
          </svg>
        </div>

        <!-- Top Observatory Telemetry Bar -->
        <div class="relative z-10 w-full max-w-6xl mx-auto px-4 sm:px-8 lg:px-12 mb-3">
          <div class="flex flex-wrap items-center justify-between gap-2 py-2 px-3.5 rounded-2xl bg-[#111622]/80 border border-[#262a35]/80 backdrop-blur-md text-[11px] font-space text-[#87929a]">
            <div class="flex items-center gap-2">
              <span class="w-2 h-2 rounded-full animate-pulse shadow-[0_0_8px_#38bdf8]" style="background-color: ${planet.colorAccent};"></span>
              <span class="text-[#dfe2f1] font-bold uppercase tracking-wider">OBSERVATORIUM KOSMIS SOL-${planet.solNumber}</span>
              <span class="text-[#38bdf8] font-mono hidden sm:inline">• STATUS: AKTIF</span>
            </div>
            <div class="flex items-center gap-3 font-mono text-[10px] text-[#bdc8d1]">
              <span class="hidden md:inline">RADIAL: ${planet.distanceAU}</span>
              <span class="hidden sm:inline">ORBIT: ${planet.orbitPeriod}</span>
              <span class="text-[#38bdf8]">J2000.0</span>
            </div>
          </div>
        </div>

        <!-- Main Responsive Grid Container -->
        <div class="relative z-10 w-full max-w-6xl mx-auto px-4 sm:px-8 lg:px-12 grid grid-cols-1 lg:grid-cols-12 items-center gap-8 lg:gap-12 my-auto">
          
          <!-- Left Column: Hero Planet Viewport & Selector -->
          <div class="lg:col-span-6 relative w-full flex flex-col items-center justify-center pt-2 pb-4">
            <!-- Planet Sphere with Orbit Aura -->
            <div class="relative flex items-center justify-center cursor-pointer group" data-action="select-planet" data-planet-id="${planet.id}" title="Buka Ensiklopedia ${planet.name}">
              ${renderPlanetSphere(planet, 'w-[220px] h-[220px] sm:w-[280px] sm:h-[280px] md:w-[330px] md:h-[330px] lg:w-[360px] lg:h-[360px]')}
            </div>

            <!-- DEDICATED PLANET CHANGER BAR -->
            <div class="relative z-20 w-full max-w-md mt-6 sm:mt-7 px-1 flex flex-col items-center gap-2.5">
              <div class="w-full flex items-center justify-between gap-1 sm:gap-2 p-1.5 sm:p-2 rounded-2xl bg-[#131724]/95 border border-[#2b3347] shadow-[0_8px_30px_rgba(0,0,0,0.65)] backdrop-blur-xl">
                <!-- Prev Button -->
                <button data-action="prev-planet" type="button" class="w-8 h-8 sm:w-9 sm:h-9 rounded-xl bg-[#1d2335] hover:bg-[#28314a] text-[#dfe2f1] hover:text-[#38bdf8] flex items-center justify-center transition-all active:scale-90 border border-white/5 cursor-pointer shrink-0" title="Planet Sebelumnya">
                  <span class="material-symbols-outlined text-[18px]">chevron_left</span>
                </button>

                <!-- Active Planet Indicator -->
                <div class="flex items-center gap-2 px-2 py-1">
                  <span class="w-2.5 h-2.5 rounded-full shadow-[0_0_8px]" style="background-color: ${planet.colorAccent}; box-shadow: 0 0 10px ${planet.colorAccent};"></span>
                  <span class="font-space text-xs sm:text-sm font-bold tracking-wide text-[#dfe2f1]">
                    ${planet.name}
                  </span>
                  <span class="font-space text-[10px] text-[#87929a] uppercase tracking-wider hidden xs:inline">
                    (Sol-${planet.solNumber})
                  </span>
                </div>

                <!-- Action Group: Shuffle & Next -->
                <div class="flex items-center gap-1.5 shrink-0">
                  <button data-action="shuffle-planet" type="button" class="flex items-center gap-1 px-2.5 py-1 sm:py-1.5 rounded-xl bg-gradient-to-r from-[#38bdf8]/20 to-[#0284c7]/20 hover:from-[#38bdf8]/35 hover:to-[#0284c7]/35 text-[#38bdf8] font-space text-[11px] font-medium border border-[#38bdf8]/40 transition-all active:scale-95 cursor-pointer" title="Ganti Planet Beranda Secara Acak">
                    <span class="material-symbols-outlined text-[15px]">autorenew</span>
                    <span class="text-[10px] sm:text-xs font-semibold">Acak</span>
                  </button>

                  <button data-action="next-planet" type="button" class="w-8 h-8 sm:w-9 sm:h-9 rounded-xl bg-[#1d2335] hover:bg-[#28314a] text-[#dfe2f1] hover:text-[#38bdf8] flex items-center justify-center transition-all active:scale-90 border border-white/5 cursor-pointer shrink-0" title="Planet Berikutnya">
                    <span class="material-symbols-outlined text-[18px]">chevron_right</span>
                  </button>
                </div>
              </div>

              <!-- Quick 8-Planet Switcher Strip (1-click select for all 8 planets) -->
              <div class="w-full flex items-center justify-between gap-1 px-1 py-1 overflow-x-auto no-scrollbar">
                ${PLANETS.map(p => {
                  const isActive = p.id === planet.id;
                  return `
                    <button data-action="set-featured-planet" data-planet-id="${p.id}" type="button" title="Pilih ${p.name}" class="flex flex-col items-center gap-1 p-1 rounded-xl transition-all duration-200 cursor-pointer ${isActive ? 'scale-110 opacity-100' : 'opacity-50 hover:opacity-100'}">
                      <div class="w-6 h-6 sm:w-7 sm:h-7 rounded-full overflow-hidden transition-all duration-200 flex items-center justify-center ${isActive ? 'ring-2 ring-offset-2 ring-offset-[#0a0e18]' : 'border border-white/20'}"
                           style="${isActive ? `border-color: ${p.colorAccent}; box-shadow: 0 0 10px ${p.colorAccent};` : ''}">
                        <img src="${p.imageUrl}" alt="${p.name}" class="w-full h-full object-cover rounded-full pointer-events-none" />
                      </div>
                      <span class="font-space text-[8px] sm:text-[9px] uppercase tracking-tighter ${isActive ? 'font-bold' : 'text-[#87929a]'}"
                            style="${isActive ? `color: ${p.colorAccent};` : ''}">
                        ${p.name.slice(0, 3)}
                      </span>
                    </button>
                  `;
                }).join('')}
              </div>
            </div>
          </div>

          <!-- Right Column: Content, Telemetry Matrix & Call to Action -->
          <div class="lg:col-span-6 flex flex-col items-center lg:items-start text-center lg:text-left px-2 sm:px-4 lg:px-0">
            <div class="flex items-center gap-2 mb-2">
              <span class="w-2 h-2 rounded-full" style="background-color: ${planet.colorAccent};"></span>
              <span class="font-space text-[11px] sm:text-xs text-[#38bdf8] tracking-widest uppercase font-semibold">
                Sektor Sol-${planet.solNumber} • ${planet.category}
              </span>
            </div>

            <h1 class="font-space text-3xl sm:text-4xl lg:text-5xl font-extrabold text-[#dfe2f1] tracking-tight leading-tight mb-3">
              ${planet.name}
            </h1>

            <p class="text-sm sm:text-base text-[#bdc8d1] max-w-lg leading-relaxed mb-5 font-normal">
              ${planet.tagline}. ${planet.description ? planet.description.slice(0, 160) + '...' : ''}
            </p>

            <!-- Telemetry 4-Matrix Grid: Makes Beranda Informative & Visually Stunning -->
            <div class="grid grid-cols-2 gap-2.5 sm:gap-3 w-full max-w-lg mb-6">
              <div class="p-3 sm:p-3.5 rounded-2xl bg-[#111622]/90 border border-[#262a35] flex flex-col text-left shadow-sm">
                <span class="text-[10px] font-space text-[#87929a] uppercase tracking-wider">Jarak ke Surya</span>
                <span class="text-sm sm:text-base font-bold font-mono text-[#38bdf8] mt-0.5">${planet.distanceAU}</span>
                <span class="text-[10px] text-[#86929d] truncate">${planet.distanceKm}</span>
              </div>

              <div class="p-3 sm:p-3.5 rounded-2xl bg-[#111622]/90 border border-[#262a35] flex flex-col text-left shadow-sm">
                <span class="text-[10px] font-space text-[#87929a] uppercase tracking-wider">Periode Orbit</span>
                <span class="text-sm sm:text-base font-bold font-mono text-[#ffb95f] mt-0.5">${planet.orbitPeriod}</span>
                <span class="text-[10px] text-[#86929d]">${planet.orbitDays || 'Revolusi Surya'}</span>
              </div>

              <div class="p-3 sm:p-3.5 rounded-2xl bg-[#111622]/90 border border-[#262a35] flex flex-col text-left shadow-sm">
                <span class="text-[10px] font-space text-[#87929a] uppercase tracking-wider">Rotasi (1 Hari)</span>
                <span class="text-sm sm:text-base font-bold font-mono text-[#a3abff] mt-0.5">${planet.dayLength}</span>
                <span class="text-[10px] text-[#86929d]">Panjang Hari</span>
              </div>

              <div class="p-3 sm:p-3.5 rounded-2xl bg-[#111622]/90 border border-[#262a35] flex flex-col text-left shadow-sm">
                <span class="text-[10px] font-space text-[#87929a] uppercase tracking-wider">Satelit Alami</span>
                <span class="text-sm sm:text-base font-bold font-mono text-[#34d399] mt-0.5">${planet.moonsCount} Bulan</span>
                <span class="text-[10px] text-[#86929d] truncate">${planet.moonsHighlight || 'Tanpa Satelit'}</span>
              </div>
            </div>

            <!-- Action Buttons Hub -->
            <div class="flex flex-wrap items-center justify-center lg:justify-start gap-3 w-full">
              <button data-action="select-planet" data-planet-id="${planet.id}" type="button" class="group px-6 py-3 rounded-2xl bg-gradient-to-r from-[#38bdf8] to-[#0284c7] text-[#00354a] font-space text-xs sm:text-sm font-bold shadow-[0_0_24px_rgba(56,189,248,0.35)] hover:shadow-[0_0_32px_rgba(56,189,248,0.55)] transition-all duration-300 hover:scale-[1.02] active:scale-95 cursor-pointer flex items-center gap-2">
                <span>Ensiklopedia Lengkap</span>
                <span class="material-symbols-outlined text-[18px] transition-transform duration-300 group-hover:translate-x-1">arrow_forward</span>
              </button>

              <button data-action="launch-orbit-with-planet" data-planet-id="${planet.id}" type="button" class="px-5 py-3 rounded-2xl bg-[#171b26]/90 hover:bg-[#262a35] text-[#dfe2f1] font-space text-xs sm:text-sm font-semibold border border-[#262a35] hover:border-[#38bdf8]/40 transition-all active:scale-95 cursor-pointer flex items-center gap-2">
                <span class="material-symbols-outlined text-[18px] text-[#38bdf8]">orbit</span>
                <span>Orbit 3D</span>
              </button>
              <button data-action="nav" data-target="asteroid_game" type="button" class="px-5 py-3 rounded-2xl bg-[#171b26]/90 hover:bg-[#262a35] text-[#dfe2f1] font-space text-xs sm:text-sm font-semibold border border-[#262a35] hover:border-emerald-400/40 transition-all active:scale-95 cursor-pointer flex items-center gap-2">
                <span class="material-symbols-outlined text-[18px] text-emerald-400">rocket_launch</span>
                <span>Misi Game</span>
              </button>

              <button data-action="nav" data-target="kuis" type="button" class="px-5 py-3 rounded-2xl bg-[#171b26]/90 hover:bg-[#262a35] text-[#dfe2f1] font-space text-xs sm:text-sm font-semibold border border-[#262a35] hover:border-[#ffb95f]/40 transition-all active:scale-95 cursor-pointer flex items-center gap-2">
                <span class="material-symbols-outlined text-[18px] text-[#ffb95f]">quiz</span>
                <span>Kuis Kosmik</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  // --- LAYAR 6: DAFTAR PLANET (ENSIKLOPEDIA STITCH DESIGN) ---
  function renderPlanetListScreen() {
    const filtered = PLANETS.filter(p => {
      const matchCat = AppState.categoryFilter === 'semua' || p.category === AppState.categoryFilter;
      const matchSearch = p.name.toLowerCase().includes(AppState.searchQuery.toLowerCase()) ||
                          p.tagline.toLowerCase().includes(AppState.searchQuery.toLowerCase()) ||
                          p.description.toLowerCase().includes(AppState.searchQuery.toLowerCase());
      return matchCat && matchSearch;
    });

    const categories = [
      { id: 'semua', label: 'Semua (8)' },
      { id: 'Planet Kebumian', label: 'Planet Kebumian' },
      { id: 'Raksasa Gas', label: 'Raksasa Gas' },
      { id: 'Raksasa Es', label: 'Raksasa Es' },
    ];

    return `
      <div class="flex flex-col w-full text-[#dfe2f1] select-none pb-24 md:pb-28 pt-2 md:pt-4">
        <div class="w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          
          <!-- Header Title & Search Filter -->
          <div class="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-6">
            <div>
              <div class="flex items-center gap-2 mb-1.5">
                <span class="w-1.5 h-1.5 rounded-full bg-[#38bdf8] animate-pulse"></span>
                <span class="font-space text-[11px] text-[#38bdf8] uppercase tracking-widest font-semibold">Katalog Astronomi</span>
              </div>
              <h1 class="font-space text-2xl sm:text-3xl lg:text-4xl font-bold tracking-tight text-[#dfe2f1]">
                Daftar Planet Tata Surya
              </h1>
            </div>

            <!-- Search input bar with clear button -->
            <div class="relative w-full md:w-80">
              <span class="material-symbols-outlined absolute left-3.5 top-1/2 -translate-y-1/2 text-[#87929a] text-[18px]">search</span>
              <input
                type="text"
                id="search-input"
                value="${AppState.searchQuery}"
                placeholder="Cari planet, nama, atau ciri..."
                class="w-full pl-10 pr-10 py-2 rounded-xl bg-[#171b26] border border-[#262a35] focus:border-[#38bdf8] text-[#dfe2f1] text-xs font-space outline-none transition-colors"
              />
              ${AppState.searchQuery ? `
                <button data-action="clear-search" type="button" class="absolute right-3 top-1/2 -translate-y-1/2 text-[#87929a] hover:text-white text-xs cursor-pointer">
                  ✕
                </button>
              ` : ''}
            </div>
          </div>

          <!-- Category filter chips -->
          <div class="flex items-center gap-2 overflow-x-auto no-scrollbar pb-3 mb-6">
            ${categories.map(c => `
              <button data-action="filter-cat" data-category="${c.id}" class="px-4 py-2 rounded-full text-xs font-space font-medium whitespace-nowrap transition-all cursor-pointer ${
                AppState.categoryFilter === c.id
                  ? 'bg-[#38bdf8] text-[#00354a] font-bold shadow-[0_0_12px_rgba(56,189,248,0.35)]'
                  : 'bg-[#171b26] text-[#87929a] hover:text-[#dfe2f1] border border-[#262a35]'
              }">
                ${c.label}
              </button>
            `).join('')}
          </div>

          <!-- Live telemetry count -->
          <div class="flex items-center justify-between text-[11px] font-space text-[#87929a] mb-4 px-1">
            <span>Menampilkan ${filtered.length} dari ${PLANETS.length} Planet Utama</span>
            <span class="text-[#38bdf8] flex items-center gap-1">
              <span class="w-1.5 h-1.5 rounded-full bg-[#38bdf8] animate-ping"></span>
              Status: Sinkron
            </span>
          </div>

          <!-- Planet Cards Grid -->
          <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5 sm:gap-6">
            ${filtered.length === 0 ? `
              <div class="col-span-full py-20 text-center text-[#87929a] bg-[#111622]/60 rounded-3xl border border-[#262a35]">
                <span class="material-symbols-outlined text-5xl mb-2 text-[#38bdf8]">search_off</span>
                <p class="font-space text-base font-semibold text-[#dfe2f1]">Planet Tidak Ditemukan</p>
                <p class="text-xs text-[#87929a] mt-1">Tidak ada hasil yang sesuai dengan kata kunci "${AppState.searchQuery}".</p>
              </div>
            ` : filtered.map(planet => {
              const isFav = AppState.favorites.includes(planet.id);
              return `
                <article class="planet-card relative flex flex-col rounded-3xl bg-gradient-to-b from-[#181d2c]/90 via-[#131622]/90 to-[#0e111a]/95 border border-[#262a35] shadow-xl overflow-hidden group hover:border-[#38bdf8]/50 transition-all duration-300">
                  <!-- Visual Planet Header Container -->
                  <div class="relative w-full aspect-square flex items-center justify-center p-4 overflow-hidden cursor-pointer" data-action="select-planet" data-planet-id="${planet.id}">
                    <div class="absolute w-44 h-44 rounded-full blur-3xl pointer-events-none opacity-30 group-hover:opacity-75 transition-all duration-500 group-hover:scale-125" style="background-color: ${planet.colorAccent};"></div>
                    <div class="relative z-10 flex items-center justify-center">
                      ${renderPlanetSphere(planet, 'w-36 h-36 sm:w-40 sm:h-40')}
                    </div>
                    <!-- Diameter Stamp Badge -->
                    <div class="absolute bottom-3 right-4 z-20 pointer-events-none">
                      <span class="font-space text-[10px] sm:text-[11px] text-[#bdc8d1]/90 tracking-wider bg-[#0a0e18]/85 px-2.5 py-0.5 rounded-full border border-[#262a35] backdrop-blur-sm shadow-md">
                        ${planet.diameterKm}
                      </span>
                    </div>
                    <!-- Favorite Button -->
                    <button data-action="toggle-fav" data-planet-id="${planet.id}" type="button" aria-label="Favorit" class="absolute top-3 right-3 z-20 w-9 h-9 rounded-full bg-[#1c1f2a]/80 backdrop-blur-md flex items-center justify-center text-[#87929a] hover:text-[#ffb95f] transition-transform active:scale-90 border border-[#3e484f]/40 cursor-pointer">
                      <span class="material-symbols-outlined text-[20px] ${isFav ? 'text-[#ffb95f]' : ''}">
                        ${isFav ? 'favorite' : 'favorite_border'}
                      </span>
                    </button>
                  </div>

                  <!-- Info Section -->
                  <div class="flex flex-col p-5">
                    <div class="flex items-center justify-between mb-1.5">
                      <span class="font-space text-[11px] text-[#38bdf8] uppercase tracking-widest font-semibold">
                        ${planet.solNumber} • ${planet.category}
                      </span>
                      <span class="w-2 h-2 rounded-full" style="background-color: ${planet.colorAccent};"></span>
                    </div>
                    <h2 class="font-space text-2xl font-bold text-[#dfe2f1] tracking-tight cursor-pointer hover:text-[#38bdf8] transition-colors" data-action="select-planet" data-planet-id="${planet.id}">
                      ${planet.name}
                    </h2>
                    <p class="text-sm text-[#bdc8d1] mt-1.5 line-clamp-2 leading-relaxed">
                      ${planet.description}
                    </p>

                    <!-- Specs Row -->
                    <div class="flex items-center gap-6 mt-4 pt-3.5 bg-[#1c1f2a]/60 -mx-5 px-5 border-t border-[#262a35]">
                      <div class="flex flex-col">
                        <span class="font-space text-[10px] text-[#87929a] uppercase tracking-wider">Jarak Rata-rata</span>
                        <span class="font-space text-sm text-[#dfe2f1] font-semibold mt-0.5">${planet.distanceAU}</span>
                      </div>
                      <div class="w-px h-6 bg-[#313540]"></div>
                      <div class="flex flex-col">
                        <span class="font-space text-[10px] text-[#87929a] uppercase tracking-wider">
                          ${planet.moonsCount > 0 ? 'Satelit Alami' : 'Durasi Hari'}
                        </span>
                        <span class="font-space text-sm text-[#dfe2f1] font-semibold mt-0.5">
                          ${planet.moonsCount > 0 ? `${planet.moonsCount} Bulan` : planet.dayLength}
                        </span>
                      </div>
                    </div>

                    <!-- Action Link -->
                    <div class="mt-4 flex items-center justify-end">
                      <button data-action="select-planet" data-planet-id="${planet.id}" type="button" class="flex items-center gap-1.5 text-[#38bdf8] hover:text-[#7bd0ff] transition-colors py-1 cursor-pointer font-space font-semibold text-xs tracking-wider">
                        <span>Lihat Detail</span>
                        <span class="material-symbols-outlined text-[18px]">arrow_forward</span>
                      </button>
                    </div>
                  </div>
                </article>
              `;
            }).join('')}
          </div>
        </div>
      </div>
    `;
  }

  // --- LAYAR 7: DETAIL PLANET (TELEMETRI 3D STITCH DESIGN) ---
  function renderPlanetDetailScreen() {
    const planet = PLANETS.find(p => p.id === (AppState.selectedPlanetId || 'jupiter')) || PLANETS[4];
    const isFav = AppState.favorites.includes(planet.id);

    return `
      <div class="flex flex-col w-full text-[#dfe2f1] pb-28 md:pb-32 select-none">
        <!-- Detail Header Terkunci (Fixed Top Bar HP & Navigasi, Tidak Bergerak saat Scroll) -->
        <header class="fixed top-0 inset-x-0 z-40 w-full bg-[#0a0e18]/90 backdrop-blur-xl border-b border-[#262a35]/60 shadow-[0_2px_15px_rgba(0,0,0,0.5)]">
          ${renderMobilePhoneTopBar(false)}
          <div class="h-14 sm:h-16 max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 flex items-center justify-between">
            <button data-action="go-back" type="button" class="inline-flex items-center gap-1.5 text-[#bdc8d1] hover:text-[#dfe2f1] transition-colors py-1.5 px-3 rounded-full bg-[#171b26] hover:bg-[#262a35] cursor-pointer font-space text-xs uppercase tracking-wider active:scale-95">
              <span class="material-symbols-outlined text-[18px] text-[#38bdf8]">arrow_back</span>
              <span>Kembali</span>
            </button>

            <div class="flex items-center gap-2">
              <span class="w-1.5 h-1.5 rounded-full bg-[#38bdf8] animate-pulse"></span>
              <span class="font-space text-[11px] sm:text-xs uppercase tracking-widest text-[#dfe2f1] font-semibold">
                ${planet.solNumber} // ${planet.category.toUpperCase()}
              </span>
            </div>

            <button data-action="toggle-fav" data-planet-id="${planet.id}" type="button" aria-label="Favorit" class="w-9 h-9 rounded-full bg-[#1c1f2a] flex items-center justify-center text-[#bdc8d1] hover:text-[#ffb95f] transition-all active:scale-90 border border-[#3e484f]/40 cursor-pointer">
              <span class="material-symbols-outlined text-[20px] ${isFav ? 'text-[#ffb95f]' : ''}">
                ${isFav ? 'favorite' : 'favorite_border'}
              </span>
            </button>
          </div>
        </header>

        <!-- Main Responsive Container -->
        <div class="w-full max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 pt-[84px] sm:pt-20">
          <div class="grid grid-cols-1 lg:grid-cols-12 gap-6 lg:gap-10 items-start">
            <!-- Left Column: Hero Planet Visual -->
            <div class="lg:col-span-5 flex flex-col items-center lg:items-start text-center lg:text-left lg:sticky lg:top-20">
              <div class="relative w-full aspect-square max-w-[300px] sm:max-w-[360px] lg:max-w-[400px] flex items-center justify-center my-2 mx-auto">
                <div class="absolute inset-0 rounded-full blur-3xl opacity-40 pointer-events-none" style="background-color: ${planet.colorAccent};"></div>
                <div class="absolute inset-4 rounded-full border border-dashed border-[#38bdf8]/25 pointer-events-none animate-spin" style="animation-duration: 60s;"></div>
                <div class="absolute inset-10 rounded-full border border-[#38bdf8]/15 pointer-events-none"></div>
                <div class="relative z-10 flex items-center justify-center">
                  ${renderPlanetSphere(planet, 'w-[230px] h-[230px] sm:w-[280px] sm:h-[280px] lg:w-[320px] lg:h-[320px]')}
                </div>
              </div>

              <div class="mt-3 w-full flex flex-col items-center lg:items-start">
                <span class="font-space text-[11px] sm:text-xs text-[#38bdf8] uppercase tracking-widest mb-1 font-semibold">
                  Planet ${planet.solNumber} · Sol-Sys
                </span>
                <h1 class="font-space text-3xl sm:text-4xl lg:text-5xl font-bold tracking-tight text-[#dfe2f1]">
                  ${planet.name}
                </h1>
                <p class="text-sm sm:text-base text-[#bdc8d1] mt-1 font-sans max-w-md">
                  ${planet.tagline}
                </p>
              </div>
            </div>

            <!-- Right Column: Specs & Telemetry -->
            <div class="lg:col-span-7 flex flex-col gap-5">
              <div class="grid grid-cols-2 gap-3.5">
                <div class="p-4 rounded-2xl bg-[#171b26]/70 border border-[#262a35] flex flex-col gap-1 shadow-sm">
                  <span class="font-space text-[11px] sm:text-xs text-[#87929a] uppercase tracking-wider">Jarak Rata-rata</span>
                  <span class="font-space text-xl sm:text-2xl font-semibold text-[#dfe2f1] tracking-tight">
                    ${planet.distanceAU} <span class="text-xs text-[#38bdf8] font-normal">AU</span>
                  </span>
                  <span class="text-[11px] sm:text-xs text-[#87929a]">${planet.distanceKm}</span>
                </div>

                <div class="p-4 rounded-2xl bg-[#171b26]/70 border border-[#262a35] flex flex-col gap-1 shadow-sm">
                  <span class="font-space text-[11px] sm:text-xs text-[#87929a] uppercase tracking-wider">Diameter</span>
                  <span class="font-space text-xl sm:text-2xl font-semibold text-[#dfe2f1] tracking-tight">
                    ${planet.diameterKm}
                  </span>
                  <span class="text-[11px] sm:text-xs text-[#87929a]">${planet.diameterRatio}</span>
                </div>

                <div class="p-4 rounded-2xl bg-[#171b26]/70 border border-[#262a35] flex flex-col gap-1 shadow-sm">
                  <span class="font-space text-[11px] sm:text-xs text-[#87929a] uppercase tracking-wider">Periode Orbit</span>
                  <span class="font-space text-xl sm:text-2xl font-semibold text-[#dfe2f1] tracking-tight">
                    ${planet.orbitPeriod}
                  </span>
                  <span class="text-[11px] sm:text-xs text-[#87929a]">${planet.orbitDays || planet.orbitPeriod}</span>
                </div>

                <div class="p-4 rounded-2xl bg-[#171b26]/70 border border-[#262a35] flex flex-col gap-1 shadow-sm">
                  <span class="font-space text-[11px] sm:text-xs text-[#87929a] uppercase tracking-wider">Satelit Alami</span>
                  <span class="font-space text-xl sm:text-2xl font-semibold text-[#dfe2f1] tracking-tight">
                    ${planet.moonsCount} <span class="text-xs text-[#a3abff] font-normal">Bulan</span>
                  </span>
                  <span class="text-[11px] sm:text-xs text-[#87929a] truncate">${planet.moonsHighlight || 'Tanpa Satelit'}</span>
                </div>
              </div>

              <!-- Extra specs bar -->
              <div class="p-4 rounded-2xl bg-[#1c1f2a]/60 border border-[#262a35] text-xs">
                <div class="grid grid-cols-3 gap-2 text-center">
                  <div class="flex flex-col items-center">
                    <span class="font-space text-[10px] sm:text-xs text-[#87929a] uppercase">Suhu Atmosfer</span>
                    <span class="font-space text-sm sm:text-base font-semibold text-[#38bdf8] mt-0.5">${planet.temperature}</span>
                  </div>
                  <div class="flex flex-col items-center border-x border-[#262a35]">
                    <span class="font-space text-[10px] sm:text-xs text-[#87929a] uppercase">Durasi Hari</span>
                    <span class="font-space text-sm sm:text-base font-semibold text-[#ffb95f] mt-0.5">${planet.dayLength}</span>
                  </div>
                  <div class="flex flex-col items-center">
                    <span class="font-space text-[10px] sm:text-xs text-[#87929a] uppercase">Tipe Geologis</span>
                    <span class="font-space text-sm sm:text-base font-semibold text-[#dfe2f1] mt-0.5">${planet.category}</span>
                  </div>
                </div>
              </div>

              <!-- About Section -->
              <div class="flex flex-col gap-2 p-5 rounded-2xl bg-[#171b26]/40 border border-[#262a35]">
                <h2 class="font-space text-xs sm:text-sm font-semibold text-[#dfe2f1] uppercase tracking-widest flex items-center gap-2">
                  <span class="w-1.5 h-1.5 rounded-full bg-[#38bdf8]"></span>
                  <span>Tentang Planet</span>
                </h2>
                <p class="text-sm sm:text-base text-[#bdc8d1] leading-relaxed font-sans">
                  ${planet.description}
                </p>
              </div>

              <!-- CTA Buttons: Launch Orbit 3D & Kuis -->
              <div class="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-2">
                <button data-action="launch-orbit-with-planet" data-planet-id="${planet.id}" type="button" class="py-3.5 px-5 rounded-full bg-[#38bdf8] hover:bg-[#7bd0ff] text-[#00354a] font-space text-sm font-semibold tracking-wide shadow-[0_0_24px_rgba(56,189,248,0.3)] hover:shadow-[0_0_32px_rgba(56,189,248,0.5)] active:scale-[0.98] transition-all flex items-center justify-center gap-2 cursor-pointer">
                  <span class="material-symbols-outlined text-[20px]">orbit</span>
                  <span>Simulasi Orbit 3D</span>
                </button>
                <button data-action="nav" data-target="kuis" type="button" class="py-3.5 px-5 rounded-full bg-[#171b26] hover:bg-[#262a35] text-[#dfe2f1] font-space text-sm font-semibold tracking-wide border border-[#262a35] active:scale-[0.98] transition-all flex items-center justify-center gap-2 cursor-pointer">
                  <span class="material-symbols-outlined text-[20px]">quiz</span>
                  <span>Uji Kuis Pengetahuan</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  // --- LAYAR 8: SIMULASI ORBIT 3D INTERAKTIF (HTML5 CANVAS 3D MURNI) ---
  function renderOrbit3DScreen() {
    const focusedPlanet = PLANETS.find(p => p.id === AppState.orbitSimulation.focusedPlanetId) || PLANETS[2]; // Default Earth
    const pitchDeg = Math.round(AppState.orbitSimulation.pitch * (180 / Math.PI));
    const isTopView = AppState.orbitSimulation.pitch >= 1.5;
    const viewLabel = isTopView ? 'Tampak Atas • 90°' : `3D • ${pitchDeg}°`;

    return `
      <div class="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 pt-4 pb-36 sm:pb-40 md:pb-44 space-y-5">
        <!-- Header Simulasi -->
        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
          <div>
            <div class="flex items-center gap-2 mb-1">
              <span class="w-2 h-2 rounded-full bg-[#38bdf8] shadow-[0_0_8px_#38bdf8] animate-pulse"></span>
              <span class="font-space text-[10px] sm:text-xs text-[#38bdf8] uppercase tracking-widest font-semibold">Observatorium Mekanika Kosmik</span>
            </div>
            <h2 class="text-xl sm:text-2xl font-bold text-white font-space">Simulasi Orbit 3D Tata Surya</h2>
            <p class="text-xs text-[#86929d] max-w-xl">Visualisasi 3D hukum Kepler dengan proyeksi ruang perspektif, depth-sorting, dan sudut pandang 360° yang dapat di-drag dan diatur bebas.</p>
          </div>

          <!-- Controls Header: Play/Pause, Speed, Reset -->
          <div class="flex items-center gap-2 self-start sm:self-center">
            <button id="btn-toggle-orbit" class="px-3.5 py-2 rounded-xl bg-[#171b26] hover:bg-[#262a35] text-xs font-mono text-[#dfe2f1] border border-[#262a35] flex items-center gap-1.5 cursor-pointer shadow-sm active:scale-95 transition-all">
              <span class="material-symbols-outlined text-[18px] text-[#38bdf8]">${AppState.orbitSimulation.isPlaying ? 'pause' : 'play_arrow'}</span>
              <span>${AppState.orbitSimulation.isPlaying ? 'Jeda' : 'Jalankan'}</span>
            </button>
            <button id="btn-speed-orbit" class="px-3 py-2 rounded-xl bg-[#38bdf8]/10 hover:bg-[#38bdf8]/20 text-xs font-mono text-[#38bdf8] border border-[#38bdf8]/30 font-bold cursor-pointer active:scale-95 transition-all">
              ${AppState.orbitSimulation.speedMultiplier}x Speed
            </button>
            <button id="btn-reset-orbit" title="Kembalikan Sudut Semula" class="p-2 rounded-xl bg-[#171b26] hover:bg-[#262a35] text-[#86929d] hover:text-[#dfe2f1] border border-[#262a35] flex items-center justify-center cursor-pointer active:scale-95 transition-all">
              <span class="material-symbols-outlined text-[18px]">restart_alt</span>
            </button>
          </div>
        </div>

        <!-- 3D Canvas Viewport Container -->
        <div class="relative w-full aspect-[4/3] sm:aspect-[16/9] md:aspect-[21/10] bg-[#05070f] rounded-3xl border border-[#262a35] overflow-hidden shadow-[0_12px_40px_rgba(0,0,0,0.7)] flex items-center justify-center select-none group cursor-grab active:cursor-grabbing">
          <canvas id="orbit-canvas" class="w-full h-full block touch-none"></canvas>

          <!-- Top-Left HUD: Solaris 1.0 AU -->
          <div class="absolute top-3.5 left-3.5 flex items-center gap-2 px-3 py-1.5 rounded-full bg-[#171b26]/90 backdrop-blur-md border border-[#262a35] text-[11px] font-mono text-[#ffb95f] pointer-events-none shadow-md">
            <span class="w-2 h-2 rounded-full bg-[#ffb95f] shadow-[0_0_8px_#ffb95f] animate-pulse"></span>
            <span>SOLARIS (1.0 AU)</span>
          </div>

          <!-- Top-Right HUD: Sudut 3D Real-time -->
          <div id="hud-angle-badge" class="absolute top-3.5 right-3.5 flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-[#171b26]/90 backdrop-blur-md border border-[#262a35] text-[11px] font-mono text-[#38bdf8] pointer-events-none shadow-md">
            <span class="material-symbols-outlined text-[15px] text-[#38bdf8]">view_in_ar</span>
            <span id="hud-angle-text">Sudut: ${viewLabel}</span>
          </div>

          <!-- Bottom-Left HUD: Petunjuk Rotasi 3D & Zoom -->
          <div class="absolute bottom-3.5 left-3.5 hidden sm:flex items-center gap-2 text-[11px] font-mono text-[#86929d] bg-[#0a0e18]/85 px-3 py-1.5 rounded-xl border border-[#262a35]/60 pointer-events-none backdrop-blur-sm">
            <span class="material-symbols-outlined text-[15px] text-[#38bdf8]">drag_pan</span>
            <span>Drag bebas untuk putar sudut orbit 3D • Scroll untuk zoom</span>
          </div>
        </div>

        <!-- Planet Selector Strip (Fokus Orbit 8 Planet) -->
        <div class="w-full flex flex-col gap-2.5">
          <div class="flex items-center justify-between">
            <span class="font-space text-[10px] sm:text-xs text-[#87929a] uppercase tracking-wider font-semibold">
              FOKUS LINTASAN ORBIT (8 PLANET UTAMA):
            </span>
            <span class="text-[11px] font-mono text-[#38bdf8]">
              Target: ${focusedPlanet.name}
            </span>
          </div>

          <div class="w-full flex items-center gap-2 overflow-x-auto pb-1 no-scrollbar">
            ${PLANETS.map(p => {
              const isFocused = p.id === focusedPlanet.id;
              return `
                <button
                  data-action="orbit-focus-planet"
                  data-planet-id="${p.id}"
                  type="button"
                  class="flex items-center gap-2 px-3 py-1.5 rounded-xl font-space text-xs whitespace-nowrap transition-all border cursor-pointer active:scale-95 ${
                    isFocused
                      ? 'bg-[#38bdf8] text-[#00354a] font-bold border-[#38bdf8] shadow-[0_0_15px_rgba(56,189,248,0.4)]'
                      : 'bg-[#171b26]/90 text-[#bdc8d1] border-[#262a35] hover:border-[#38bdf8]/40 hover:text-white'
                  }"
                >
                  <span class="w-2 h-2 rounded-full" style="background-color: ${p.colorAccent}"></span>
                  <span>${p.name}</span>
                </button>
              `;
            }).join('')}
          </div>
        </div>

        <!-- Focused Planet Telemetry & Orbit Card -->
        <div id="orbit-planet-card" class="w-full rounded-3xl bg-gradient-to-br from-[#171b26]/95 via-[#131620]/90 to-[#0f1118]/95 border border-[#262a35] p-5 sm:p-6 shadow-xl relative overflow-hidden backdrop-blur-md">
          <div class="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-5">
            <!-- Left: Planet Info -->
            <div class="flex items-center gap-4">
              <div class="w-16 h-16 sm:w-20 sm:h-20 rounded-2xl overflow-hidden bg-[#07090e] border border-[#38bdf8]/30 shrink-0 p-1 flex items-center justify-center shadow-[0_0_20px_rgba(56,189,248,0.15)]">
                <img src="${focusedPlanet.imageUrl}" alt="${focusedPlanet.name}" class="w-full h-full object-cover rounded-xl" />
              </div>
              <div>
                <div class="flex items-center gap-2 mb-1">
                  <span class="px-2 py-0.5 rounded-full text-[10px] font-mono bg-[#38bdf8]/15 text-[#38bdf8] border border-[#38bdf8]/30">SOL-${focusedPlanet.solNumber}</span>
                  <span class="text-xs text-[#87929a] font-space">${focusedPlanet.category}</span>
                </div>
                <h3 class="text-xl sm:text-2xl font-bold text-white font-space">${focusedPlanet.name}</h3>
                <p class="text-xs text-[#86929d] mt-0.5">${focusedPlanet.tagline}</p>
              </div>
            </div>

            <!-- Middle: 4 Key Orbital Metrics -->
            <div class="grid grid-cols-2 sm:grid-cols-4 gap-3 w-full lg:w-auto">
              <div class="p-3 rounded-2xl bg-[#0b0e17]/80 border border-[#262a35]/80 flex flex-col">
                <span class="text-[10px] font-space text-[#87929a] uppercase">Periode Orbit</span>
                <span class="text-sm font-bold font-mono text-white mt-0.5">${focusedPlanet.orbitDays || focusedPlanet.orbitPeriod}</span>
                <span class="text-[10px] text-[#86929d]">Revolusi Penuh</span>
              </div>
              <div class="p-3 rounded-2xl bg-[#0b0e17]/80 border border-[#262a35]/80 flex flex-col">
                <span class="text-[10px] font-space text-[#87929a] uppercase">Jarak Surya</span>
                <span class="text-sm font-bold font-mono text-[#38bdf8] mt-0.5">${focusedPlanet.distanceAU}</span>
                <span class="text-[10px] text-[#86929d]">${focusedPlanet.distanceKm}</span>
              </div>
              <div class="p-3 rounded-2xl bg-[#0b0e17]/80 border border-[#262a35]/80 flex flex-col">
                <span class="text-[10px] font-space text-[#87929a] uppercase">Kecepatan Orbit</span>
                <span class="text-sm font-bold font-mono text-[#ffb95f] mt-0.5">${focusedPlanet.realSpeedKmS || '30.0 km/s'}</span>
                <span class="text-[10px] text-[#86929d]">Relatif Kepler</span>
              </div>
              <div class="p-3 rounded-2xl bg-[#0b0e17]/80 border border-[#262a35]/80 flex flex-col">
                <span class="text-[10px] font-space text-[#87929a] uppercase">Kemiringan Orbit</span>
                <span class="text-sm font-bold font-mono text-[#a3abff] mt-0.5">${focusedPlanet.inclination ?? '0.00'}°</span>
                <span class="text-[10px] text-[#86929d]">Ke Bidang Ekliptika</span>
              </div>
            </div>

            <!-- Right: Action Button to Open Planet Detail -->
            <button
              data-action="select-planet"
              data-planet-id="${focusedPlanet.id}"
              type="button"
              class="w-full lg:w-auto px-5 py-3 rounded-2xl bg-[#38bdf8] hover:bg-[#7bd0ff] text-[#00354a] font-space text-xs font-bold tracking-wide transition-all shadow-[0_0_20px_rgba(56,189,248,0.25)] hover:shadow-[0_0_28px_rgba(56,189,248,0.4)] active:scale-95 flex items-center justify-center gap-2 cursor-pointer shrink-0"
            >
              <span>Ensiklopedia Planet</span>
              <span class="material-symbols-outlined text-[16px]">arrow_forward</span>
            </button>
          </div>
        </div>
      </div>
    `;
  }

  // --- LAYAR 9: KUIS KOSMIS (TABBED QUIZ: 10 SOAL PER TAB) ---
  function renderQuizScreen() {
    const activeTab = AppState.quiz.activeTab || 0;
    const tabQuestions = QUIZ_QUESTIONS.filter(q => q.tabIndex === activeTab);
    
    // Pastikan currentQuestionId valid untuk tab aktif
    let currentQ = tabQuestions.find(q => q.id === AppState.quiz.currentQuestionId);
    if (!currentQ && tabQuestions.length > 0) {
      currentQ = tabQuestions[0];
      AppState.quiz.currentQuestionId = currentQ.id;
    }

    const currentAnswer = currentQ ? AppState.quiz.answers[currentQ.id] : null;
    const isCurrentAnswered = !!currentAnswer;

    // Hitung progress per tab
    const tabsInfo = [
      { id: 0, title: 'Paket 1', subtitle: 'Planet Kebumian (1–10)', icon: 'public' },
      { id: 1, title: 'Paket 2', subtitle: 'Planet Luar & Sabuk (11–20)', icon: 'all_inclusive' },
      { id: 2, title: 'Paket 3', subtitle: 'Mekanika & Eksplorasi (21–30)', icon: 'rocket_launch' },
    ];

    const tabAnswers = tabQuestions.filter(q => !!AppState.quiz.answers[q.id]);
    const isTabCompleted = tabAnswers.length === tabQuestions.length && tabQuestions.length > 0;
    const tabScore = tabQuestions.reduce((acc, q) => {
      const ans = AppState.quiz.answers[q.id];
      return acc + (ans && ans.isCorrect ? (ans.points || 100) : 0);
    }, 0);
    const tabCorrectCount = tabQuestions.filter(q => AppState.quiz.answers[q.id]?.isCorrect).length;

    // Index soal relatif terhadap tab (0-9)
    const qIndexInTab = tabQuestions.findIndex(q => q.id === (currentQ ? currentQ.id : -1));

    return `
      <div class="flex flex-col w-full max-w-4xl mx-auto px-3.5 sm:px-6 lg:px-8 pt-2 pb-36 sm:pb-40 md:pb-44 select-none relative">
        <!-- Header Info Kuis -->
        <header class="pb-3 flex flex-col gap-2">
          <!-- Baris 1: Akademi Tag & Skor Total -->
          <div class="flex items-center justify-between gap-2">
            <div class="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-[#111622]/90 border border-[#38bdf8]/30">
              <span class="inline-block w-2 h-2 rounded-full bg-[#38bdf8] animate-pulse shadow-[0_0_8px_rgba(56,189,248,0.8)]"></span>
              <span class="font-space text-[10px] sm:text-xs text-[#38bdf8] uppercase tracking-wider font-semibold">
                AKADEMI ASTRONOMI
              </span>
            </div>

            <div class="flex items-center gap-1.5 px-2.5 sm:px-3 py-1 rounded-full bg-[#1c1f2a] border border-[#ffb95f]/40 backdrop-blur-md">
              <span class="material-symbols-outlined text-[14px] text-[#ffb95f]">stars</span>
              <span class="font-space text-[11px] sm:text-xs text-[#ffb95f] uppercase tracking-wider font-bold">
                ${AppState.quiz.score} PTS
              </span>
            </div>
          </div>

          <!-- Baris 2: Judul & Status Progress Soal -->
          <div class="flex flex-col sm:flex-row sm:items-baseline justify-between gap-1 mt-0.5">
            <h1 class="font-space text-xl sm:text-3xl text-[#dfe2f1] font-bold tracking-tight">
              Kuis Kosmik Tata Surya
            </h1>
            <div class="flex items-center gap-2">
              <span class="font-space text-[11px] sm:text-xs text-[#87929a]">
                Tuntas: <span class="text-[#38bdf8] font-bold">${Object.keys(AppState.quiz.answers).length}</span> / 30 Soal
              </span>
              <!-- Mini Progress Bar -->
              <div class="w-14 sm:w-24 h-1.5 rounded-full bg-[#171b26] border border-[#262a35] overflow-hidden">
                <div class="h-full bg-gradient-to-r from-[#38bdf8] to-emerald-400 transition-all duration-300" style="width: ${(Object.keys(AppState.quiz.answers).length / 30) * 100}%"></div>
              </div>
            </div>
          </div>

          <p class="text-xs sm:text-sm text-[#bdc8d1] leading-relaxed">
            Pilihlah paket pertanyaan di bawah. Tiap paket berisi 10 soal kurasi ilmiah.
          </p>

          <!-- 3 TAB NAVIGATION BAR (10 SOAL PER TAB) -->
          <div class="grid grid-cols-3 gap-1.5 sm:gap-2.5 mt-2 p-1 sm:p-1.5 rounded-2xl bg-[#111622]/90 border border-[#262a35] backdrop-blur-md">
            ${tabsInfo.map(tab => {
              const isActive = activeTab === tab.id;
              const answeredInThis = QUIZ_QUESTIONS.filter(q => q.tabIndex === tab.id && AppState.quiz.answers[q.id]).length;
              const isAllDone = answeredInThis === 10;
              const shortLabel = tab.id === 0 ? 'Planet Dalam' : (tab.id === 1 ? 'Planet Luar' : 'Eksplorasi');
              return `
                <button
                  type="button"
                  data-action="quiz-switch-tab"
                  data-tab="${tab.id}"
                  class="flex flex-col items-center justify-center py-2 sm:py-2.5 px-1 sm:px-2 rounded-xl transition-all duration-200 cursor-pointer text-center relative ${
                    isActive
                      ? 'bg-gradient-to-r from-[#38bdf8] to-[#0284c7] text-[#00354a] font-bold shadow-[0_0_15px_rgba(56,189,248,0.35)]'
                      : 'text-[#87929a] hover:text-[#dfe2f1] hover:bg-[#171b26]'
                  }"
                >
                  <div class="flex items-center gap-1 sm:gap-1.5">
                    <span class="material-symbols-outlined text-[14px] sm:text-[16px]">${tab.icon}</span>
                    <span class="font-space text-xs sm:text-sm font-bold uppercase tracking-wider">${tab.title}</span>
                  </div>
                  <span class="text-[9px] sm:text-[10px] truncate max-w-full font-space mt-0.5 ${isActive ? 'text-[#002838]' : 'text-[#87929a]'}">
                    <span class="inline sm:hidden">${shortLabel}</span>
                    <span class="hidden sm:inline">${tab.subtitle}</span>
                  </span>
                  <div class="mt-1 flex items-center gap-1">
                    <span class="text-[9px] font-mono px-1.5 py-0.5 rounded-full ${
                      isActive
                        ? 'bg-black/20 text-[#002838] font-bold'
                        : isAllDone
                        ? 'bg-emerald-500/20 text-emerald-400 font-semibold'
                        : 'bg-[#262a35] text-[#bdc8d1]'
                    }">
                      ${answeredInThis}/10 ${isAllDone ? '✓' : ''}
                    </span>
                  </div>
                </button>
              `;
            }).join('')}
          </div>
        </header>

        <!-- 10-QUESTION SELECTOR STRIP FOR ACTIVE TAB -->
        <div class="w-full bg-[#131724]/90 border border-[#262a35] rounded-2xl p-2.5 sm:p-3 mb-4 backdrop-blur-md">
          <div class="flex items-center justify-between text-[11px] font-space text-[#87929a] mb-2 px-1">
            <span class="font-semibold uppercase tracking-wider text-[#dfe2f1]">
              Pilih Nomor Soal (${tabsInfo[activeTab].title}):
            </span>
            <span class="text-[#38bdf8] font-medium">
              ${tabAnswers.length}/10 Terjawab
            </span>
          </div>
          <div class="grid grid-cols-5 sm:grid-cols-10 gap-1.5 sm:gap-2">
            ${tabQuestions.map((q, idx) => {
              const ans = AppState.quiz.answers[q.id];
              const isSelected = currentQ && currentQ.id === q.id;
              let btnStyle = 'bg-[#171b26] text-[#bdc8d1] border-[#262a35] hover:border-[#38bdf8]/40';
              let badge = '';

              if (ans) {
                if (ans.isCorrect) {
                  btnStyle = 'bg-emerald-500/20 text-emerald-300 border-emerald-500/60 font-bold';
                  badge = '✓';
                } else {
                  btnStyle = 'bg-rose-500/20 text-rose-300 border-rose-500/60 font-bold';
                  badge = '✕';
                }
              }

              if (isSelected) {
                btnStyle += ' ring-2 ring-[#38bdf8] ring-offset-2 ring-offset-[#0a0e18] shadow-[0_0_12px_rgba(56,189,248,0.4)]';
              }

              return `
                <button
                  type="button"
                  data-action="quiz-jump-question"
                  data-qid="${q.id}"
                  class="flex flex-col items-center justify-center h-10 sm:h-11 rounded-xl border text-xs font-space font-semibold transition-all duration-150 cursor-pointer active:scale-95 ${btnStyle}"
                  title="Soal ${q.id}: ${q.question.slice(0, 30)}..."
                >
                  <span class="text-[11px] sm:text-xs font-mono font-bold leading-none">${String(idx + 1).padStart(2, '0')}</span>
                  ${badge ? `<span class="text-[10px] font-bold leading-none mt-0.5">${badge}</span>` : `<span class="text-[9px] opacity-40 font-mono leading-none mt-0.5">#${q.id}</span>`}
                </button>
              `;
            }).join('')}
          </div>
        </div>

        <!-- TAB COMPLETION BANNER IF ALL 10 ARE ANSWERED -->
        ${isTabCompleted ? `
          <div class="w-full bg-gradient-to-r from-[#171b26] via-[#1a2335] to-[#171b26] border border-[#38bdf8]/40 rounded-2xl p-4 sm:p-5 mb-4 shadow-lg flex flex-col sm:flex-row items-center justify-between gap-4">
            <div class="flex items-center gap-3">
              <div class="w-12 h-12 rounded-xl bg-[#38bdf8]/15 border border-[#38bdf8]/40 text-[#38bdf8] flex items-center justify-center shrink-0">
                <span class="material-symbols-outlined text-2xl">verified</span>
              </div>
              <div>
                <h3 class="font-space text-base font-bold text-white">${tabsInfo[activeTab].title} Tuntas!</h3>
                <p class="text-xs text-[#bdc8d1]">Benar: <span class="text-emerald-400 font-bold">${tabCorrectCount}/10</span> • Poin Paket: <span class="text-[#38bdf8] font-bold">${tabScore} PTS</span></p>
              </div>
            </div>
            <div class="flex items-center gap-2 w-full sm:w-auto">
              <button
                type="button"
                data-action="quiz-reset-tab"
                data-tab="${activeTab}"
                class="flex-1 sm:flex-initial px-4 py-2 rounded-xl bg-[#262a35] hover:bg-[#323746] text-[#dfe2f1] font-space text-xs font-semibold border border-[#3e484f]/40 transition-all cursor-pointer"
              >
                Ulangi Paket Ini
              </button>
              ${activeTab < 2 ? `
                <button
                  type="button"
                  data-action="quiz-switch-tab"
                  data-tab="${activeTab + 1}"
                  class="flex-1 sm:flex-initial px-5 py-2 rounded-xl bg-[#38bdf8] hover:bg-[#7bd0ff] text-[#00354a] font-space text-xs font-bold transition-all shadow-[0_0_15px_rgba(56,189,248,0.3)] cursor-pointer flex items-center justify-center gap-1"
                >
                  <span>Paket Berikutnya</span>
                  <span class="material-symbols-outlined text-[16px]">arrow_forward</span>
                </button>
              ` : ''}
            </div>
          </div>
        ` : ''}

        <!-- QUIZ ACTIVE QUESTION CARD -->
        ${currentQ ? `
          <div class="w-full bg-gradient-to-b from-[#1c1f2a]/95 via-[#1c1f2a]/85 to-[#171b26]/95 backdrop-blur-2xl rounded-3xl p-4 sm:p-7 border border-[#262a35] shadow-[0_8px_32px_rgba(0,0,0,0.45)] flex flex-col gap-4 sm:gap-5 relative overflow-hidden">
            <!-- Top Category & Number Indicators -->
            <div class="flex flex-wrap sm:flex-nowrap items-center justify-between gap-2 relative z-10">
              <div class="flex items-center gap-1.5 sm:gap-2 px-2.5 sm:px-3 py-1 sm:py-1.5 rounded-full bg-[#262a35]/80 border border-[#ffb95f]/30 shadow-sm">
                <span class="w-2 h-2 rounded-full bg-[#ffb95f] animate-pulse shadow-[0_0_6px_rgba(255,185,95,0.8)]"></span>
                <span class="font-space text-[10px] sm:text-xs text-[#ffddb8] uppercase tracking-wider font-semibold">
                  ${currentQ.category}
                </span>
              </div>

              <div class="flex items-center gap-2">
                <span class="px-2.5 py-1 rounded-full bg-[#38bdf8]/10 text-[#38bdf8] border border-[#38bdf8]/30 font-mono text-[10px] sm:text-[11px] font-bold">
                  +${currentQ.points} PTS
                </span>
                <div class="px-2.5 sm:px-3 py-1 rounded-full bg-[#262a35]/60 border border-[#3e484f]/40 font-space text-[10px] sm:text-xs text-[#87929a] tracking-wider font-medium">
                  Soal ${qIndexInTab + 1} / 10 (No. ${currentQ.id})
                </div>
              </div>
            </div>

            <!-- Question Heading -->
            <div class="relative z-10">
              <h2 class="font-space text-base sm:text-xl lg:text-2xl text-[#dfe2f1] font-semibold tracking-tight leading-snug sm:leading-snug">
                ${currentQ.question}
              </h2>
            </div>

            <!-- Options Grid (1 kolom pada ponsel, 2 kolom pada layar lebar) -->
            <div class="grid grid-cols-1 sm:grid-cols-2 gap-2.5 sm:gap-3 pt-0.5 sm:pt-1 relative z-10">
              ${currentQ.options.map(option => {
                const isSelected = currentAnswer && currentAnswer.selectedKey === option.key;
                const isCorrect = option.key === currentQ.correctKey;
                let optionStyle = 'bg-[#171b26]/80 hover:bg-[#262a35] border-[#3e484f]/40 text-[#bdc8d1]';

                if (isCurrentAnswered) {
                  if (isCorrect) {
                    optionStyle = 'bg-emerald-500/20 border-2 border-emerald-400 text-emerald-300 font-semibold shadow-[0_0_20px_rgba(16,185,129,0.3)]';
                  } else if (isSelected && !isCorrect) {
                    optionStyle = 'bg-rose-500/20 border-2 border-rose-400 text-rose-300 font-semibold';
                  } else {
                    optionStyle = 'bg-[#171b26]/50 border-[#262a35] text-[#87929a] opacity-60';
                  }
                }

                return `
                  <button
                    type="button"
                    data-action="quiz-select"
                    data-choice="${option.key}"
                    data-qid="${currentQ.id}"
                    ${isCurrentAnswered ? 'disabled' : ''}
                    class="w-full min-h-[50px] sm:min-h-[56px] p-3 sm:p-3.5 rounded-2xl border flex items-center justify-between text-left transition-all active:scale-[0.99] cursor-pointer ${optionStyle}"
                  >
                    <div class="flex items-center gap-2.5 sm:gap-3 min-w-0 flex-1">
                      <span class="w-6 h-6 sm:w-7 sm:h-7 rounded-lg flex items-center justify-center font-space text-xs font-bold shrink-0 transition-colors ${
                        isCurrentAnswered && isCorrect
                          ? 'bg-emerald-400 text-[#00354a]'
                          : isCurrentAnswered && isSelected && !isCorrect
                          ? 'bg-rose-400 text-[#00354a]'
                          : 'bg-[#262a35] text-[#dfe2f1]'
                      }">
                        ${option.key}
                      </span>
                      <span class="text-xs sm:text-sm font-medium leading-relaxed break-words">${option.text}</span>
                    </div>

                    ${isCurrentAnswered && isCorrect ? `
                      <div class="w-5 h-5 rounded-full bg-emerald-400 flex items-center justify-center shadow-sm shrink-0 ml-2">
                        <span class="material-symbols-outlined text-[#00354a] text-[16px] font-bold">check</span>
                      </div>
                    ` : ''}

                    ${isCurrentAnswered && isSelected && !isCorrect ? `
                      <div class="w-5 h-5 rounded-full bg-rose-400 flex items-center justify-center shadow-sm shrink-0 ml-2">
                        <span class="material-symbols-outlined text-[#00354a] text-[16px] font-bold">close</span>
                      </div>
                    ` : ''}
                  </button>
                `;
              }).join('')}
            </div>

            <!-- Explanation Box & Action Buttons -->
            ${isCurrentAnswered ? `
              <div id="quiz-answered-box" class="pt-1 sm:pt-2 flex flex-col gap-3 relative z-10">
                <div class="p-3.5 sm:p-4 rounded-2xl bg-[#262a35]/80 border border-[#38bdf8]/30 text-xs sm:text-sm text-[#bdc8d1] shadow-md">
                  <div class="flex items-center gap-1.5 text-[#38bdf8] font-space font-semibold uppercase text-[11px] mb-1">
                    <span class="material-symbols-outlined text-[16px]">info</span>
                    <span>Fakta Astronomi:</span>
                  </div>
                  <p class="leading-relaxed">${currentQ.explanation}</p>
                </div>

                <!-- Action Buttons with Safe Navbar Clearance -->
                <div class="flex items-center gap-2 pt-1">
                  ${qIndexInTab > 0 ? `
                    <button
                      type="button"
                      data-action="quiz-prev"
                      class="px-4 sm:px-5 py-2.5 sm:py-3 rounded-full bg-[#171b26] hover:bg-[#262a35] text-[#dfe2f1] font-space text-xs font-semibold border border-[#3e484f]/40 active:scale-[0.98] transition-all cursor-pointer flex items-center gap-1 sm:gap-1.5"
                    >
                      <span class="material-symbols-outlined text-[16px] sm:text-[18px]">arrow_back</span>
                      <span>Sebelumnya</span>
                    </button>
                  ` : ''}

                  <button
                    id="btn-quiz-next"
                    data-action="quiz-next"
                    type="button"
                    class="flex-1 h-11 sm:h-13 rounded-full bg-gradient-to-r from-[#38bdf8] via-[#60a5fa] to-[#c4e7ff] text-[#00354a] font-space text-xs sm:text-sm tracking-wider uppercase font-bold flex items-center justify-center gap-1.5 sm:gap-2 shadow-[0_4px_24px_rgba(56,189,248,0.35)] hover:shadow-[0_4px_32px_rgba(56,189,248,0.55)] active:scale-[0.98] transition-all cursor-pointer"
                  >
                    <span>${qIndexInTab === 9 ? (activeTab < 2 ? 'Lanjut ke Paket Berikutnya' : 'Selesaikan Semua Kuis') : 'Soal Berikutnya'}</span>
                    <span class="material-symbols-outlined text-[18px] sm:text-[20px] font-bold">arrow_forward</span>
                  </button>
                </div>
              </div>
            ` : `
              <!-- Jika belum dijawab, tetap berikan tombol untuk beralih nomor -->
              <div class="flex items-center justify-between text-xs text-[#87929a] pt-1">
                <span>Pilih jawaban di atas untuk melihat fakta astronomi</span>
                ${qIndexInTab > 0 ? `
                  <button type="button" data-action="quiz-prev" class="text-[#38bdf8] hover:underline flex items-center gap-1 cursor-pointer">
                    <span class="material-symbols-outlined text-[15px]">arrow_back</span>
                    <span>Soal Sebelumnya</span>
                  </button>
                ` : ''}
              </div>
            `}
          </div>
        ` : ''}
      </div>
    `;
  }

  // --- LAYAR: MINI GAME SABUK ASTEROID ---
  function renderAsteroidGameScreen() {
    const bestScore = AppState.asteroidGame ? AppState.asteroidGame.highScore : 0;

    return `
      <div class="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 pt-3 sm:pt-4 pb-32 sm:pb-36 space-y-4 sm:space-y-5 select-none">
        <!-- Header Bar Simulasi Misi -->
        <div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
          <div>
            <div class="flex items-center gap-2 mb-1">
              <span class="w-2 h-2 rounded-full bg-emerald-400 shadow-[0_0_8px_#34d399] animate-pulse"></span>
              <span class="font-space text-[10px] sm:text-xs text-emerald-400 uppercase tracking-widest font-semibold">
                MISI KOKPIT // SOL-MAIN-BELT
              </span>
            </div>
            <h2 class="text-xl sm:text-2xl font-bold text-white font-space">
              Sabuk Asteroid: Misi Hindaran Pesawat
            </h2>
            <p class="text-xs text-[#86929d] max-w-xl">
              Kendalikan pesawat antariksa menembus ribuan batuan kosmik antara Mars dan Jupiter. Ambil Kristal Stardust, aktifkan Perisai Hologram, dan gunakan Warp Drive!
            </p>
          </div>

          <!-- Header Action Badges -->
          <div class="flex items-center gap-2 self-start sm:self-center">
            <div class="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-[#171b26] border border-[#262a35] text-xs font-mono text-[#ffb95f]">
              <span class="material-symbols-outlined text-[16px] text-[#ffb95f]">military_tech</span>
              <span>Rekor: <strong id="game-header-best">${bestScore}</strong> km</span>
            </div>
            <button
              id="btn-game-sound-toggle"
              data-action="game-toggle-sound"
              type="button"
              title="Suara Efek Misi"
              class="p-2 rounded-xl bg-[#171b26] hover:bg-[#262a35] text-[#86929d] hover:text-[#dfe2f1] border border-[#262a35] flex items-center justify-center cursor-pointer active:scale-95 transition-all"
            >
              <span class="material-symbols-outlined text-[18px]" id="game-sound-icon">volume_up</span>
            </button>
            <button
              id="btn-game-pause-toggle"
              data-action="game-toggle-pause"
              type="button"
              title="Jeda Misi"
              class="px-3 py-2 rounded-xl bg-[#171b26] hover:bg-[#262a35] text-xs font-mono text-[#dfe2f1] border border-[#262a35] flex items-center gap-1.5 cursor-pointer shadow-sm active:scale-95 transition-all"
            >
              <span class="material-symbols-outlined text-[16px] text-emerald-400" id="game-pause-icon">pause</span>
              <span id="game-pause-text">Jeda</span>
            </button>
          </div>
        </div>

        <!-- Game Canvas Viewport Container (Proporsional di Desktop & Ringkas Rapi di Mobile) -->
        <div class="relative w-full h-[290px] sm:h-[380px] md:h-[500px] lg:h-[540px] max-h-[75vh] bg-[#050711] rounded-3xl border border-[#262a35] overflow-hidden shadow-[0_16px_50px_rgba(0,0,0,0.8)] flex items-center justify-center select-none group">
          <!-- Canvas Game HTML5 -->
          <canvas id="asteroid-game-canvas" class="w-full h-full block touch-none cursor-crosshair"></canvas>

          <!-- Top Floating In-Game HUD -->
          <div class="absolute top-2.5 inset-x-2.5 sm:inset-x-5 flex items-center justify-between pointer-events-none z-20">
            <!-- Left: Distance & Velocity -->
            <div class="flex items-center gap-1.5 sm:gap-2">
              <div class="flex items-center gap-1 sm:gap-1.5 px-2.5 sm:px-3 py-1 sm:py-1.5 rounded-full bg-[#0a0e18]/90 backdrop-blur-md border border-[#3e484f]/40 text-xs font-space text-[#dfe2f1] shadow-lg">
                <span class="material-symbols-outlined text-[14px] sm:text-[16px] text-emerald-400 animate-pulse">rocket</span>
                <span class="font-bold text-emerald-300 text-[11px] sm:text-xs" id="game-hud-dist">0</span>
                <span class="text-[9px] sm:text-[10px] text-[#87929a]">KM</span>
              </div>
              <div class="hidden sm:flex items-center gap-1 px-2.5 py-1 rounded-full bg-[#0a0e18]/80 backdrop-blur-md border border-[#262a35] text-[10px] font-mono text-[#bdc8d1]">
                <span id="game-hud-speed">1.0x VELOCITY</span>
              </div>
            </div>

            <!-- Center: Warp Charge Meter -->
            <div class="flex items-center gap-1 sm:gap-1.5 px-2.5 sm:px-3 py-1 sm:py-1.5 rounded-full bg-[#0a0e18]/90 backdrop-blur-md border border-[#3e484f]/40 text-xs font-mono shadow-lg">
              <span class="material-symbols-outlined text-[14px] sm:text-[15px] text-amber-400">bolt</span>
              <span class="text-[10px] sm:text-[11px] text-amber-300 font-bold hidden sm:inline">WARP</span>
              <div class="w-14 sm:w-24 h-1.5 sm:h-2 rounded-full bg-[#171b26] border border-[#3e484f]/50 overflow-hidden">
                <div id="game-warp-progress" class="h-full bg-gradient-to-r from-amber-500 to-amber-300 w-full transition-all duration-150"></div>
              </div>
            </div>

            <!-- Right: Crystals & Shields -->
            <div class="flex items-center gap-1.5 sm:gap-2">
              <div class="flex items-center gap-1 px-2 sm:px-2.5 py-1 sm:py-1.5 rounded-full bg-[#0a0e18]/90 backdrop-blur-md border border-[#3e484f]/40 text-xs font-space text-[#38bdf8] shadow-lg">
                <span class="material-symbols-outlined text-[14px] sm:text-[16px] text-[#38bdf8]">diamond</span>
                <span class="font-bold text-[11px] sm:text-xs" id="game-hud-crystals">0</span>
              </div>
              <div class="flex items-center gap-1 px-2 sm:px-2.5 py-1 sm:py-1.5 rounded-full bg-[#0a0e18]/90 backdrop-blur-md border border-[#3e484f]/40 text-xs font-space text-cyan-300 shadow-lg">
                <span class="material-symbols-outlined text-[14px] sm:text-[16px] text-cyan-400">shield</span>
                <span class="font-bold text-[11px] sm:text-xs" id="game-hud-shields">1</span>
              </div>
            </div>
          </div>

          <!-- Start Mission Modal Overlay (Responsif Mobile & Rapi, Pas Proporsional) -->
          <div id="game-start-overlay" class="absolute inset-0 z-30 bg-[#070a13]/95 backdrop-blur-md flex flex-col items-center justify-center p-3 sm:p-5 text-center transition-all duration-300 overflow-y-auto no-scrollbar">
            <div class="my-auto flex flex-col items-center w-full max-w-sm">
              <div class="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full bg-[#1c2230] border border-emerald-500/40 text-emerald-400 text-[10px] sm:text-xs font-space uppercase tracking-widest font-semibold mb-1.5 sm:mb-2">
                <span class="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-ping"></span>
                <span>Simulasi Kokpit Antariksa</span>
              </div>
              <h3 class="font-space text-lg sm:text-2xl font-bold text-white mb-1 tracking-tight">
                Sabuk Asteroid: Misi Hindaran
              </h3>
              <p class="text-[11px] sm:text-xs text-[#bdc8d1] max-w-xs mb-2.5 sm:mb-3.5 leading-snug">
                Kemudikan pesawat menembus batuan asteroid. Kumpulkan Kristal, gunakan Perisai & Warp Drive!
              </p>

              <!-- Feature Instructions Grid (Compact 3-Card Deck) -->
              <div class="grid grid-cols-3 gap-1.5 sm:gap-2.5 w-full mb-3 sm:mb-4 text-center">
                <div class="p-1.5 sm:p-2 rounded-xl bg-[#171b26]/90 border border-[#262a35]">
                  <span class="material-symbols-outlined text-[16px] sm:text-[18px] text-emerald-400 mb-0.5">gamepad</span>
                  <p class="font-space text-[10px] sm:text-[11px] font-semibold text-[#dfe2f1]">4 Arah</p>
                  <p class="text-[9px] text-[#87929a]">◀ ▲ ▶ ▼</p>
                </div>
                <div class="p-1.5 sm:p-2 rounded-xl bg-[#171b26]/90 border border-[#262a35]">
                  <span class="material-symbols-outlined text-[16px] sm:text-[18px] text-[#38bdf8] mb-0.5">diamond</span>
                  <p class="font-space text-[10px] sm:text-[11px] font-semibold text-[#dfe2f1]">Kristal</p>
                  <p class="text-[9px] text-[#87929a]">+50 KM</p>
                </div>
                <div class="p-1.5 sm:p-2 rounded-xl bg-[#171b26]/90 border border-[#262a35]">
                  <span class="material-symbols-outlined text-[16px] sm:text-[18px] text-amber-400 mb-0.5">bolt</span>
                  <p class="font-space text-[10px] sm:text-[11px] font-semibold text-[#dfe2f1]">Warp</p>
                  <p class="text-[9px] text-[#87929a]">Daya Kebal</p>
                </div>
              </div>

              <!-- Start Button (Muncul Utuh di Ponsel) -->
              <button
                id="btn-start-asteroid-game"
                data-action="start-asteroid-game"
                type="button"
                class="w-full sm:w-auto px-6 py-2.5 sm:py-3 rounded-full bg-gradient-to-r from-emerald-400 via-teal-400 to-[#38bdf8] text-[#00354a] font-space text-xs sm:text-sm font-bold shadow-[0_0_20px_rgba(52,211,153,0.4)] hover:shadow-[0_0_30px_rgba(52,211,153,0.6)] active:scale-95 transition-all cursor-pointer flex items-center justify-center gap-1.5 shrink-0"
              >
                <span class="material-symbols-outlined text-[18px]">rocket_launch</span>
                <span>Luncurkan Pesawat (Mulai Misi)</span>
              </button>
            </div>
          </div>

          <!-- Pause Overlay -->
          <div id="game-pause-overlay" class="hidden absolute inset-0 z-30 bg-[#070a13]/90 backdrop-blur-md flex flex-col items-center justify-center p-3 sm:p-5 text-center overflow-y-auto no-scrollbar">
            <div class="my-auto flex flex-col items-center w-full max-w-xs">
              <div class="w-10 h-10 sm:w-12 sm:h-12 rounded-full bg-[#171b26] border border-emerald-500/40 flex items-center justify-center mb-2 text-emerald-400 shadow-lg shrink-0">
                <span class="material-symbols-outlined text-[22px] sm:text-[26px]">pause</span>
              </div>
              <h3 class="font-space text-lg sm:text-xl font-bold text-white mb-1">Misi Dijeda</h3>
              <p class="text-[11px] sm:text-xs text-[#86929d] mb-3 sm:mb-4">Sistem transmisi kokpit ditahan sementara.</p>
              <div class="flex items-center gap-2.5 w-full justify-center">
                <button
                  data-action="game-toggle-pause"
                  type="button"
                  class="flex-1 px-4 py-2 rounded-full bg-emerald-400 text-[#00354a] font-space text-xs font-bold shadow-md cursor-pointer active:scale-95 transition-all flex items-center justify-center"
                >
                  Lanjut
                </button>
                <button
                  data-action="restart-asteroid-game"
                  type="button"
                  class="flex-1 px-4 py-2 rounded-full bg-[#171b26] hover:bg-[#262a35] text-xs font-space text-[#dfe2f1] border border-[#262a35] cursor-pointer active:scale-95 transition-all flex items-center justify-center"
                >
                  Ulang
                </button>
              </div>
            </div>
          </div>

          <!-- Game Over Overlay -->
          <div id="game-over-overlay" class="hidden absolute inset-0 z-30 bg-[#070a13]/95 backdrop-blur-lg flex flex-col items-center justify-center p-3 sm:p-4 text-center overflow-y-auto no-scrollbar">
            <div class="my-auto flex flex-col items-center w-full max-w-sm">
              <div class="w-10 h-10 sm:w-12 sm:h-12 rounded-full bg-rose-500/15 border border-rose-500/30 flex items-center justify-center mb-1.5 text-rose-400 shadow-xl shrink-0">
                <span class="material-symbols-outlined text-[22px] sm:text-[26px]">warning</span>
              </div>
              <div class="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full bg-rose-500/20 text-rose-300 text-[9px] font-space uppercase tracking-widest font-semibold mb-1">
                <span>BENTURAN KOSMIS</span>
              </div>
              <h3 class="font-space text-base sm:text-2xl font-bold text-white mb-0.5">
                Pesawat Tertabrak Asteroid!
              </h3>
              <p class="text-[10px] sm:text-xs text-[#86929d] max-w-xs mb-2">
                Modul penjelajah mengalami kerusakan struktural.
              </p>

              <!-- Mission Telemetry Summary Card -->
              <div class="w-full rounded-xl bg-[#171b26]/90 border border-[#3e484f]/40 p-2.5 sm:p-3 shadow-xl mb-2.5 space-y-1.5 text-left text-xs">
                <div class="flex items-center justify-between pb-1 border-b border-[#262a35]">
                  <span class="text-[#86929d]">Jarak:</span>
                  <span class="font-space font-bold text-emerald-400" id="game-over-dist">0 km</span>
                </div>
                <div class="flex items-center justify-between pb-1 border-b border-[#262a35]">
                  <span class="text-[#86929d]">Kristal:</span>
                  <span class="font-space font-bold text-[#38bdf8]" id="game-over-crystals">0</span>
                </div>
                <div class="flex items-center justify-between pb-1 border-b border-[#262a35]">
                  <span class="text-[#86929d]">Skor:</span>
                  <span class="font-space font-bold text-[#ffb95f]" id="game-over-score">0 pts</span>
                </div>
                <div class="flex items-center justify-between">
                  <span class="text-[#86929d]">Pangkat:</span>
                  <span class="font-space font-bold text-[#dfe2f1] text-[11px]" id="game-over-rank">Kadet Kosmik</span>
                </div>
              </div>

              <!-- Action Buttons -->
              <div class="flex items-center justify-center gap-2 w-full shrink-0">
                <button
                  data-action="restart-asteroid-game"
                  type="button"
                  class="flex-1 px-4 py-2 rounded-full bg-gradient-to-r from-emerald-400 to-[#38bdf8] text-[#00354a] font-space text-xs font-bold shadow-[0_0_15px_rgba(52,211,153,0.4)] active:scale-95 transition-all flex items-center justify-center gap-1 cursor-pointer"
                >
                  <span class="material-symbols-outlined text-[16px]">replay</span>
                  <span>Main Lagi</span>
                </button>
                <button
                  data-action="nav"
                  data-target="beranda"
                  type="button"
                  class="flex-1 px-4 py-2 rounded-full bg-[#171b26] hover:bg-[#262a35] text-xs font-space text-[#dfe2f1] border border-[#262a35] active:scale-95 transition-all cursor-pointer flex items-center justify-center"
                >
                  <span>Beranda</span>
                </button>
              </div>
            </div>
          </div>
        </div>

        <!-- Touch & Keyboard Steering Deck (4 Arah: Atas, Bawah, Kiri, Kanan + Warp Drive) -->
        <div class="w-full flex flex-col sm:flex-row items-center justify-between gap-3 p-3 sm:p-4 rounded-2xl bg-[#171b26]/85 border border-[#262a35] backdrop-blur-xl shadow-lg">
          <!-- 4-Way Directional D-Pad (Kemudi: Atas, Bawah, Kiri, Kanan) -->
          <div class="flex items-center justify-between sm:justify-start gap-2.5 w-full sm:w-auto">
            <div class="grid grid-cols-3 gap-1.5 w-36 sm:w-44 select-none touch-manipulation">
              <div></div>
              <button
                id="btn-steer-up"
                type="button"
                aria-label="Kemudi Atas"
                class="h-10 sm:h-11 rounded-xl bg-[#262a35] hover:bg-[#323746] active:bg-emerald-500/30 active:scale-95 text-[#dfe2f1] hover:text-emerald-300 border border-[#3e484f]/50 flex items-center justify-center cursor-pointer transition-all shadow-md select-none touch-manipulation group"
              >
                <span class="material-symbols-outlined text-[24px] group-active:-translate-y-0.5 transition-transform">keyboard_arrow_up</span>
              </button>
              <div></div>

              <button
                id="btn-steer-left"
                type="button"
                aria-label="Kemudi Kiri"
                class="h-10 sm:h-11 rounded-xl bg-[#262a35] hover:bg-[#323746] active:bg-emerald-500/30 active:scale-95 text-[#dfe2f1] hover:text-emerald-300 border border-[#3e484f]/50 flex items-center justify-center cursor-pointer transition-all shadow-md select-none touch-manipulation group"
              >
                <span class="material-symbols-outlined text-[24px] group-active:-translate-x-0.5 transition-transform">keyboard_arrow_left</span>
              </button>
              <button
                id="btn-steer-down"
                type="button"
                aria-label="Kemudi Bawah"
                class="h-10 sm:h-11 rounded-xl bg-[#262a35] hover:bg-[#323746] active:bg-emerald-500/30 active:scale-95 text-[#dfe2f1] hover:text-emerald-300 border border-[#3e484f]/50 flex items-center justify-center cursor-pointer transition-all shadow-md select-none touch-manipulation group"
              >
                <span class="material-symbols-outlined text-[24px] group-active:translate-y-0.5 transition-transform">keyboard_arrow_down</span>
              </button>
              <button
                id="btn-steer-right"
                type="button"
                aria-label="Kemudi Kanan"
                class="h-10 sm:h-11 rounded-xl bg-[#262a35] hover:bg-[#323746] active:bg-emerald-500/30 active:scale-95 text-[#dfe2f1] hover:text-emerald-300 border border-[#3e484f]/50 flex items-center justify-center cursor-pointer transition-all shadow-md select-none touch-manipulation group"
              >
                <span class="material-symbols-outlined text-[24px] group-active:translate-x-0.5 transition-transform">keyboard_arrow_right</span>
              </button>
            </div>

            <!-- Warp Booster Trigger on Mobile (Right beside D-Pad for thumbs) -->
            <button
              id="btn-trigger-warp"
              data-action="game-trigger-warp"
              type="button"
              class="flex-1 sm:hidden h-full min-h-[88px] px-3 py-2 rounded-2xl bg-gradient-to-br from-amber-500 via-amber-400 to-amber-300 text-[#451a03] font-space text-[11px] uppercase tracking-wider font-bold shadow-[0_0_20px_rgba(245,158,11,0.35)] active:scale-95 transition-all flex flex-col items-center justify-center gap-1 cursor-pointer select-none touch-manipulation"
            >
              <span class="material-symbols-outlined text-[24px]">bolt</span>
              <span class="font-bold leading-tight">WARP DRIVE</span>
              <span class="text-[9px] font-mono opacity-80">KEBAL 4 DETIK</span>
            </button>
          </div>

          <!-- Warp Booster Trigger on Desktop/Tablet -->
          <div class="hidden sm:flex items-center justify-center flex-1 max-w-xs">
            <button
              id="btn-trigger-warp-desktop"
              data-action="game-trigger-warp"
              type="button"
              class="w-full px-6 py-3.5 rounded-2xl bg-gradient-to-r from-amber-500 via-amber-400 to-amber-300 text-[#451a03] font-space text-xs uppercase tracking-wider font-bold shadow-[0_0_20px_rgba(245,158,11,0.35)] hover:shadow-[0_0_30px_rgba(245,158,11,0.55)] active:scale-95 transition-all flex items-center justify-center gap-2 cursor-pointer select-none touch-manipulation"
            >
              <span class="material-symbols-outlined text-[20px]">bolt</span>
              <span>AKTIFKAN WARP DRIVE (SPASI)</span>
            </button>
          </div>

          <!-- Keyboard Hint -->
          <div class="hidden lg:flex flex-col items-end text-[11px] font-mono text-[#86929d] space-y-0.5">
            <div class="flex items-center gap-1.5 text-[#dfe2f1]">
              <span class="material-symbols-outlined text-[15px] text-[#38bdf8]">sports_esports</span>
              <span>W A S D / Tombol Panah (▲ ◀ ▼ ▶)</span>
            </div>
            <div class="text-[10px] text-[#6b7280]">
              Sentuh langsung layar canvas / Tekan Spasi untuk Warp
            </div>
          </div>
        </div>
      </div>
    `;
  }


  // --- LAYAR 10: PROFIL PENJELAJAH ---
  function renderProfileScreen() {
    const favCount = AppState.favorites.length;
    const answeredCount = Object.keys(AppState.quiz.answers || {}).length;
    const favPlanet = PLANETS.find(p => p.id === (AppState.user.favoritePlanet || 'saturnus')) || PLANETS[5];

    return `
      <div class="max-w-3xl mx-auto px-4 sm:px-6 pt-4 pb-36 sm:pb-40 md:pb-44 space-y-6 select-none">
        <!-- Hero Profile Card -->
        <div class="bg-gradient-to-b from-[#131724]/95 to-[#0e111a]/95 border border-[#262a35] rounded-3xl p-6 sm:p-8 text-center shadow-2xl relative overflow-hidden backdrop-blur-xl">
          <!-- Background Ambient Glow -->
          <div class="absolute -top-24 left-1/2 -translate-x-1/2 w-64 h-64 rounded-full bg-[#38bdf8]/15 blur-3xl pointer-events-none"></div>

          <!-- Avatar with Tier Ring -->
          <div class="relative w-24 h-24 rounded-full mx-auto mb-4 p-1 ring-2 ring-[#38bdf8]/60 shadow-[0_0_30px_rgba(56,189,248,0.3)]">
            <img
              src="${AppState.user.avatarUrl}"
              alt="${AppState.user.name}"
              class="w-full h-full object-cover rounded-full bg-[#111622]"
              onerror="this.src='https://images.unsplash.com/photo-1541872703-74c5e44368f9?w=300&q=80'"
            />
            <span class="absolute bottom-0 right-0 w-6 h-6 rounded-full bg-[#10b981] border-2 border-[#0e111a] flex items-center justify-center text-white" title="Status: Online & Mengorbit">
              <span class="w-2 h-2 rounded-full bg-white animate-ping"></span>
            </span>
          </div>

          <h2 class="text-2xl sm:text-3xl font-bold text-white font-space">${AppState.user.name}</h2>
          <div class="flex items-center justify-center gap-2 mt-1 mb-2">
            <span class="px-2.5 py-0.5 rounded-full text-[11px] font-mono bg-[#38bdf8]/15 text-[#38bdf8] border border-[#38bdf8]/30">
              CALLSIGN: ${AppState.user.callsign}
            </span>
            <span class="px-2.5 py-0.5 rounded-full text-[11px] font-mono bg-[#ffb95f]/15 text-[#ffb95f] border border-[#ffb95f]/30">
              ${AppState.user.agency || 'Badan Antariksa'}
            </span>
          </div>
          <p class="text-xs text-[#86929d] mb-4 max-w-md mx-auto font-mono">${AppState.user.email}</p>

          ${AppState.user.bio ? `
            <p class="text-xs sm:text-sm text-[#bdc8d1] max-w-lg mx-auto italic bg-[#171b26]/70 p-3 rounded-xl border border-[#262a35] mb-5">
              "${AppState.user.bio}"
            </p>
          ` : ''}

          <!-- Edit Profile Action Button -->
          <div class="flex justify-center mb-6">
            <button
              data-action="nav"
              data-target="edit_profile"
              type="button"
              class="inline-flex items-center gap-2 px-6 py-2.5 rounded-full bg-gradient-to-r from-[#38bdf8] to-[#0284c7] text-[#00354a] font-space text-xs font-bold shadow-[0_0_20px_rgba(56,189,248,0.3)] hover:shadow-[0_0_28px_rgba(56,189,248,0.5)] active:scale-95 transition-all cursor-pointer"
            >
              <span class="material-symbols-outlined text-[18px]">edit</span>
              <span>Edit Profil Pengguna</span>
            </button>
          </div>

          <!-- Stats Grid: Skor, Kuis, Favorit -->
          <div class="grid grid-cols-3 gap-3 pt-6 border-t border-[#262a35]">
            <div class="p-3 rounded-2xl bg-[#171b26]/80 border border-[#262a35]/60 flex flex-col items-center">
              <span class="text-[10px] font-mono text-[#86929d] uppercase">SKOR TOTAL</span>
              <span class="text-base sm:text-lg font-bold text-[#38bdf8] font-space mt-0.5">${AppState.user.score} PTS</span>
            </div>
            <div class="p-3 rounded-2xl bg-[#171b26]/80 border border-[#262a35]/60 flex flex-col items-center">
              <span class="text-[10px] font-mono text-[#86929d] uppercase">SOAL DIJAWAB</span>
              <span class="text-base sm:text-lg font-bold text-[#a3abff] font-space mt-0.5">${answeredCount}/30</span>
            </div>
            <div class="p-3 rounded-2xl bg-[#171b26]/80 border border-[#262a35]/60 flex flex-col items-center">
              <span class="text-[10px] font-mono text-[#86929d] uppercase">PLANET FAVORIT</span>
              <span class="text-base sm:text-lg font-bold text-[#ffb95f] font-space mt-0.5">${favPlanet.name}</span>
            </div>
          </div>
        </div>

        <!-- Menu Opsi Profil -->
        <div class="bg-[#111622]/90 border border-[#262a35] rounded-2xl overflow-hidden shadow-lg backdrop-blur-md">
          <button data-action="nav" data-target="edit_profile" class="w-full px-5 py-4 flex items-center justify-between border-b border-[#262a35] hover:bg-[#171b26] transition-colors cursor-pointer text-left">
            <div class="flex items-center gap-3 text-sm font-medium text-white">
              <span class="material-symbols-outlined text-[#38bdf8]">manage_accounts</span>
              <span>Edit Identitas & Avatar Kosmik</span>
            </div>
            <span class="material-symbols-outlined text-[#86929d] text-sm">chevron_right</span>
          </button>

          <button data-action="nav" data-target="favorites" class="w-full px-5 py-4 flex items-center justify-between border-b border-[#262a35] hover:bg-[#171b26] transition-colors cursor-pointer text-left">
            <div class="flex items-center gap-3 text-sm font-medium text-white">
              <span class="material-symbols-outlined text-[#f43f5e]">favorite</span>
              <span>Planet Favorit Tersimpan (${favCount})</span>
            </div>
            <span class="material-symbols-outlined text-[#86929d] text-sm">chevron_right</span>
          </button>

          <button data-action="nav" data-target="theme_settings" class="w-full px-5 py-4 flex items-center justify-between border-b border-[#262a35] hover:bg-[#171b26] transition-colors cursor-pointer text-left">
            <div class="flex items-center gap-3 text-sm font-medium text-white">
              <span class="material-symbols-outlined text-[#a3abff]">palette</span>
              <span>Preferensi Tampilan & Aksen</span>
            </div>
            <span class="material-symbols-outlined text-[#86929d] text-sm">chevron_right</span>
          </button>

          <button data-action="logout" class="w-full px-5 py-4 flex items-center justify-between hover:bg-[#171b26] text-[#ef4444] transition-colors cursor-pointer text-left">
            <div class="flex items-center gap-3 text-sm font-medium">
              <span class="material-symbols-outlined">logout</span>
              <span>Keluar dari Kokpit</span>
            </div>
            <span class="material-symbols-outlined text-sm">chevron_right</span>
          </button>
        </div>
      </div>
    `;
  }

  // --- LAYAR TAMBAHAN: EDIT PROFIL PENJELAJAH ---
  function renderEditProfileScreen() {
    return `
      <div class="max-w-2xl mx-auto px-4 sm:px-6 pt-2 pb-36 sm:pb-40 md:pb-44 select-none">
        <!-- Top Navigation -->
        <div class="flex items-center justify-between mb-4">
          <button data-action="go-back" type="button" class="inline-flex items-center gap-1.5 text-[#bdc8d1] hover:text-[#dfe2f1] transition-colors py-1 cursor-pointer font-space text-xs uppercase tracking-wider">
            <span class="material-symbols-outlined text-[18px] text-[#38bdf8]">arrow_back</span>
            <span>Kembali</span>
          </button>
          <span class="font-space text-xs text-[#87929a] uppercase tracking-wider">PENGATURAN IDENTITAS</span>
        </div>

        <!-- Form Card -->
        <div class="bg-gradient-to-b from-[#131724]/95 to-[#0f121d]/95 border border-[#262a35] rounded-3xl p-6 sm:p-8 shadow-2xl backdrop-blur-xl">
          <div class="flex items-center gap-3 mb-6">
            <div class="w-10 h-10 rounded-xl bg-[#38bdf8]/15 border border-[#38bdf8]/30 flex items-center justify-center text-[#38bdf8]">
              <span class="material-symbols-outlined">badge</span>
            </div>
            <div>
              <h2 class="text-xl font-bold text-white font-space">Edit Profil Penjelajah</h2>
              <p class="text-xs text-[#86929d]">Perbarui identitas astronot, callsign, dan preferensi misi</p>
            </div>
          </div>

          <form id="form-edit-profile" class="space-y-5" onsubmit="event.preventDefault();">
            <!-- Preset Avatar Selector -->
            <div>
              <label class="block text-xs font-mono text-[#86929d] uppercase mb-2">Pilih Avatar Kosmik</label>
              <div class="grid grid-cols-3 sm:grid-cols-6 gap-2.5">
                ${PRESET_AVATARS.map(item => {
                  const isSelected = AppState.user.avatarUrl === item.url;
                  return `
                    <button
                      type="button"
                      data-action="select-preset-avatar"
                      data-avatar-url="${item.url}"
                      class="flex flex-col items-center p-1.5 rounded-2xl border transition-all cursor-pointer active:scale-95 ${
                        isSelected
                          ? 'border-[#38bdf8] bg-[#38bdf8]/15 shadow-[0_0_12px_rgba(56,189,248,0.4)]'
                          : 'border-[#262a35] hover:border-[#38bdf8]/40 bg-[#171b26]'
                      }"
                    >
                      <img src="${item.url}" alt="${item.name}" class="w-12 h-12 rounded-xl object-cover" />
                      <span class="text-[9px] font-mono text-[#dfe2f1] mt-1 truncate max-w-full">${item.name}</span>
                    </button>
                  `;
                }).join('')}
              </div>
            </div>

            <!-- Custom Avatar URL (Opsional) -->
            <div>
              <label class="block text-xs font-mono text-[#86929d] uppercase mb-1">Atau URL Foto / Avatar Kustom</label>
              <input
                type="url"
                id="edit-user-avatar-url"
                value="${AppState.user.avatarUrl || ''}"
                placeholder="https://images.unsplash.com/..."
                class="w-full bg-[#171b26] border border-[#262a35] focus:border-[#38bdf8] rounded-xl px-4 py-2.5 text-xs font-mono text-[#dfe2f1] outline-none transition-colors"
              />
            </div>

            <!-- Nama Lengkap & Callsign -->
            <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label class="block text-xs font-mono text-[#86929d] uppercase mb-1">Nama Lengkap</label>
                <input
                  type="text"
                  id="edit-user-name"
                  required
                  value="${AppState.user.name || ''}"
                  placeholder="Contoh: Alif Saefullah"
                  class="w-full bg-[#171b26] border border-[#262a35] focus:border-[#38bdf8] rounded-xl px-4 py-2.5 text-sm text-[#dfe2f1] outline-none transition-colors font-space"
                />
              </div>

              <div>
                <label class="block text-xs font-mono text-[#86929d] uppercase mb-1">Callsign Kosmik</label>
                <input
                  type="text"
                  id="edit-user-callsign"
                  required
                  value="${AppState.user.callsign || ''}"
                  placeholder="Contoh: ORION-9"
                  class="w-full bg-[#171b26] border border-[#262a35] focus:border-[#38bdf8] rounded-xl px-4 py-2.5 text-sm text-[#dfe2f1] outline-none transition-colors font-mono uppercase"
                />
              </div>
            </div>

            <!-- Email & Lembaga/Agency -->
            <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label class="block text-xs font-mono text-[#86929d] uppercase mb-1">Email Astronom</label>
                <input
                  type="email"
                  id="edit-user-email"
                  required
                  value="${AppState.user.email || ''}"
                  placeholder="email@kosmik.org"
                  class="w-full bg-[#171b26] border border-[#262a35] focus:border-[#38bdf8] rounded-xl px-4 py-2.5 text-sm text-[#dfe2f1] outline-none transition-colors"
                />
              </div>

              <div>
                <label class="block text-xs font-mono text-[#86929d] uppercase mb-1">Lembaga / Afiliasi Antariksa</label>
                <input
                  type="text"
                  id="edit-user-agency"
                  value="${AppState.user.agency || 'Badan Antariksa Nasional'}"
                  placeholder="Contoh: Badan Antariksa Nasional"
                  class="w-full bg-[#171b26] border border-[#262a35] focus:border-[#38bdf8] rounded-xl px-4 py-2.5 text-sm text-[#dfe2f1] outline-none transition-colors font-space"
                />
              </div>
            </div>

            <!-- Planet Favorit Utama -->
            <div>
              <label class="block text-xs font-mono text-[#86929d] uppercase mb-1">Planet Favorit Utama</label>
              <select
                id="edit-user-favplanet"
                class="w-full bg-[#171b26] border border-[#262a35] focus:border-[#38bdf8] rounded-xl px-4 py-2.5 text-sm text-[#dfe2f1] outline-none transition-colors font-space cursor-pointer"
              >
                ${PLANETS.map(p => `
                  <option value="${p.id}" ${AppState.user.favoritePlanet === p.id ? 'selected' : ''}>
                    ${p.name} (Sol-${p.solNumber}) — ${p.category}
                  </option>
                `).join('')}
              </select>
            </div>

            <!-- Bio / Moto Misi -->
            <div>
              <label class="block text-xs font-mono text-[#86929d] uppercase mb-1">Bio / Moto Misi Eksplorasi</label>
              <textarea
                id="edit-user-bio"
                rows="3"
                placeholder="Tuliskan visi kosmik atau catatan misi Anda..."
                class="w-full bg-[#171b26] border border-[#262a35] focus:border-[#38bdf8] rounded-xl px-4 py-2.5 text-sm text-[#dfe2f1] outline-none transition-colors font-sans"
              >${AppState.user.bio || ''}</textarea>
            </div>

            <!-- Submit & Cancel Action Buttons -->
            <div class="flex items-center gap-3 pt-4 border-t border-[#262a35]">
              <button
                type="button"
                data-action="save-profile"
                class="flex-1 py-3.5 rounded-xl bg-gradient-to-r from-[#38bdf8] to-[#0284c7] text-[#00354a] font-space text-xs sm:text-sm font-bold tracking-wider uppercase shadow-[0_0_20px_rgba(56,189,248,0.35)] hover:shadow-[0_0_28px_rgba(56,189,248,0.55)] active:scale-95 transition-all cursor-pointer flex items-center justify-center gap-2"
              >
                <span class="material-symbols-outlined text-[18px]">save</span>
                <span>Simpan Perubahan</span>
              </button>

              <button
                type="button"
                data-action="go-back"
                class="px-6 py-3.5 rounded-xl bg-[#171b26] hover:bg-[#262a35] text-[#dfe2f1] font-space text-xs font-semibold border border-[#3e484f]/40 active:scale-95 transition-all cursor-pointer"
              >
                Batal
              </button>
            </div>
          </form>
        </div>
      </div>
    `;
  }

  // --- LAYAR 11: FAVORIT SCREEN ---
